CREATE OR REPLACE FUNCTION public._merge_identity_refs(_survivor uuid, _victim uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_keys text[];
  v_ext jsonb;
BEGIN
  IF _survivor = _victim THEN RETURN; END IF;

  -- Repoint referencing rows.
  UPDATE public.card_images      SET identity_id = _survivor      WHERE identity_id = _victim;
  UPDATE public.price_observations SET identity_id = _survivor    WHERE identity_id = _victim;
  UPDATE public.sold_comps       SET identity_id = _survivor      WHERE identity_id = _victim;
  UPDATE public.vault_cards      SET master_identity_id = _survivor WHERE master_identity_id = _victim;
  UPDATE public.vault_cards      SET card_identity_id = _survivor  WHERE card_identity_id = _victim;
  UPDATE public.wishlist_items   SET card_identity_id = _survivor  WHERE card_identity_id = _victim;

  -- Consolidate provider_keys (array) + external_ids (jsonb) onto survivor.
  SELECT
    ARRAY(
      SELECT DISTINCT k FROM unnest(
        COALESCE(s.provider_keys, '{}') || COALESCE(v.provider_keys, '{}')
      ) AS k WHERE k IS NOT NULL AND k <> ''
    ),
    COALESCE(v.external_ids, '{}'::jsonb) || COALESCE(s.external_ids, '{}'::jsonb)
  INTO v_keys, v_ext
  FROM public.card_identities s, public.card_identities v
  WHERE s.id = _survivor AND v.id = _victim;

  UPDATE public.card_identities
  SET provider_keys = v_keys, external_ids = v_ext
  WHERE id = _survivor;

  DELETE FROM public.card_identities WHERE id = _victim;
END;
$function$

CREATE OR REPLACE FUNCTION public.accept_seller_agreement(_version text DEFAULT '1.0'::text, _user_agent text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _at timestamptz := now();
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;

  INSERT INTO public.legal_acceptances (user_id, document_type, version, user_agent, accepted_at)
  VALUES (_uid, 'seller_agreement', _version, LEFT(_user_agent, 200), _at)
  ON CONFLICT (user_id, document_type, version) DO UPDATE
    SET accepted_at = COALESCE(public.legal_acceptances.accepted_at, EXCLUDED.accepted_at);

  UPDATE public.profiles
  SET seller_agreement_version = _version,
      seller_agreement_accepted_at = _at,
      seller_agreement_review_required = false
  WHERE id = _uid;

  RETURN jsonb_build_object('version', _version, 'accepted_at', _at);
END;
$function$

CREATE OR REPLACE FUNCTION public.add_business_days(_from timestamp with time zone, _days integer)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  d timestamptz := _from;
  added int := 0;
BEGIN
  WHILE added < _days LOOP
    d := d + interval '1 day';
    IF EXTRACT(ISODOW FROM d) < 6 THEN
      added := added + 1;
    END IF;
  END LOOP;
  RETURN d;
END $function$

CREATE OR REPLACE FUNCTION public.add_stream_minutes(_user_id uuid, _minutes integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  total integer;
  badge text;
BEGIN
  IF _minutes IS NULL OR _minutes <= 0 THEN RETURN; END IF;
  UPDATE public.profiles
    SET total_stream_minutes = total_stream_minutes + _minutes
    WHERE id = _user_id
    RETURNING total_stream_minutes INTO total;
  IF total IS NULL THEN RETURN; END IF;
  badge := CASE
    WHEN total >= 3000 THEN 'platinum'
    WHEN total >= 500  THEN 'gold'
    WHEN total >= 100  THEN 'silver'
    ELSE 'none'
  END;
  UPDATE public.profiles SET streaming_badge = badge WHERE id = _user_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_apply_buyer_restriction(_user_id uuid, _kind text, _reason text, _cents_limit integer DEFAULT NULL::integer, _expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
BEGIN
  IF NOT (has_role(auth.uid(), 'admin'::app_role) OR has_role(auth.uid(), 'owner'::app_role)) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  INSERT INTO public.buyer_restrictions (
    user_id, kind, cents_limit, reason, created_by, expires_at
  ) VALUES (
    _user_id, _kind, _cents_limit, _reason, auth.uid(), _expires_at
  ) RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_assign_role(_target_user uuid, _role app_role)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _caller uuid := auth.uid();
BEGIN
  IF _caller IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF _role = 'owner' THEN RAISE EXCEPTION 'Owner cannot be assigned'; END IF;
  IF public.has_role(_caller, 'owner') THEN
    NULL;
  ELSIF public.has_role(_caller, 'admin') THEN
    IF _role = 'admin' THEN RAISE EXCEPTION 'Only the owner can grant admin'; END IF;
  ELSE
    RAISE EXCEPTION 'Insufficient permissions';
  END IF;
  IF public.has_role(_target_user, 'owner') THEN
    RAISE EXCEPTION 'Cannot modify owner roles';
  END IF;
  INSERT INTO public.user_roles (user_id, role) VALUES (_target_user, _role)
  ON CONFLICT (user_id, role) DO NOTHING;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_ban_buyer(_buyer uuid, _notes text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _c uuid := auth.uid();
BEGIN
  IF NOT (public.has_role(_c,'admin') OR public.has_role(_c,'owner')) THEN RAISE EXCEPTION 'Insufficient permissions'; END IF;
  UPDATE public.profiles SET bid_restricted_until = now() + interval '100 years', bid_restricted_reason='Permanent ban' WHERE id=_buyer;
  BEGIN INSERT INTO public.user_suspensions (user_id, reason, active) VALUES (_buyer, COALESCE(_notes,'Banned by admin'), true);
  EXCEPTION WHEN OTHERS THEN NULL; END;
  UPDATE public.buyer_review_queue SET status='banned', resolved_by=_c, resolved_at=now(), resolution_notes=_notes WHERE buyer_id=_buyer AND status='pending';
END $function$

CREATE OR REPLACE FUNCTION public.admin_extend_buyer_restriction(_buyer uuid, _days integer, _notes text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _c uuid := auth.uid();
BEGIN
  IF NOT (public.has_role(_c,'admin') OR public.has_role(_c,'owner') OR public.has_role(_c,'moderator')) THEN RAISE EXCEPTION 'Insufficient permissions'; END IF;
  UPDATE public.profiles SET bid_restricted_until = GREATEST(COALESCE(bid_restricted_until, now()), now()) + make_interval(days => GREATEST(1,_days)),
    bid_restricted_reason = COALESCE(bid_restricted_reason, 'Extended by admin') WHERE id=_buyer;
  UPDATE public.buyer_review_queue SET status='extended', resolved_by=_c, resolved_at=now(), resolution_notes=_notes WHERE buyer_id=_buyer AND status='pending';
END $function$

CREATE OR REPLACE FUNCTION public.admin_force_rearm(_stream_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _caller uuid := auth.uid();
BEGIN
  IF _caller IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
