    '/legal/seller-host-agreement');
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_identity_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  result jsonb;
  v_total int;
  v_legacy int;
  v_dup_extra int;
  v_dup_groups int;
  v_pk_collisions int;
  v_orphans int;
  v_bad_lang int;
  v_sample jsonb;
begin
  if not public.has_role(auth.uid(), 'admin') then
    raise exception 'admin only';
  end if;

  select count(*) into v_total from public.card_identities;

  -- Runtime computeFingerprint() always yields exactly 32 lowercase hex chars.
  -- Anything else (e.g. the legacy "bf_" backfill format) can never be matched
  -- on rescan and WILL spawn a duplicate identity.
  select count(*) into v_legacy
  from public.card_identities
  where fingerprint !~ '^[0-9a-f]{32}$';

  -- Logical duplicates: same card information resolved to >1 master row.
  with grp as (
    select count(*) c
    from public.card_identities
    group by category, lower(name), lower(coalesce(set_code, set_name, '')),
             lower(coalesce(number, '')), lower(coalesce(language, ''))
    having count(*) > 1
  )
  select coalesce(sum(c - 1), 0), count(*) into v_dup_extra, v_dup_groups from grp;

  -- One market-data provider key should map to exactly ONE master identity.
  select count(*) into v_pk_collisions from (
    select pk from (
      select unnest(provider_keys) pk, id from public.card_identities
    ) t group by pk having count(distinct id) > 1
  ) x;

  select count(*) into v_orphans
  from public.vault_cards where master_identity_id is null;

  select count(*) into v_bad_lang
  from public.card_identities
  where language is null
     or language not in ('en','jp','zh','ko','fr','de','es','it','pt','ru');

  select coalesce(jsonb_agg(row_to_json(s)), '[]'::jsonb) into v_sample
  from (
    select category, name, coalesce(set_code, set_name) as set, number, language,
           count(*) as copies, array_agg(id) as ids
    from public.card_identities
    group by category, lower(name), lower(coalesce(set_code, set_name, '')),
             lower(coalesce(number, '')), lower(coalesce(language, '')),
             category, name, coalesce(set_code, set_name), number, language
    having count(*) > 1
    order by count(*) desc
    limit 25
  ) s;

  result := jsonb_build_object(
    'total_identities', v_total,
    'legacy_format_count', v_legacy,
    'duplicate_extra_rows', v_dup_extra,
    'duplicate_groups', v_dup_groups,
    'provider_key_collisions', v_pk_collisions,
    'orphan_vault_cards', v_orphans,
    'bad_language_codes', v_bad_lang,
    'duplicate_samples', v_sample,
    'generated_at', now()
  );
  return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_merge_identities(_actor uuid, _survivor uuid, _victims uuid[], _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v uuid;
  merged int := 0;
BEGIN
  IF NOT public.has_role(_actor, 'admin') THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;
  IF _survivor IS NULL OR NOT EXISTS (SELECT 1 FROM public.card_identities WHERE id = _survivor) THEN
    RAISE EXCEPTION 'Survivor identity not found';
  END IF;

  FOREACH v IN ARRAY _victims LOOP
    IF v IS NOT NULL AND v <> _survivor
       AND EXISTS (SELECT 1 FROM public.card_identities WHERE id = v) THEN
      PERFORM public._merge_identity_refs(_survivor, v);
      merged := merged + 1;
    END IF;
  END LOOP;

  INSERT INTO public.admin_action_log (admin_id, action, target_table, target_id, after_state, reason)
  VALUES (_actor, 'identity_merge', 'card_identities', _survivor,
          jsonb_build_object('survivor', _survivor, 'victims', _victims, 'merged', merged),
          _reason);

  RETURN jsonb_build_object('survivor', _survivor, 'merged', merged);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_override_trust(_user_id uuid, _instant_pct integer, _frozen boolean, _reason text)
 RETURNS seller_trust
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _row public.seller_trust;
BEGIN
  IF NOT (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'owner')) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  IF _instant_pct IS NOT NULL AND (_instant_pct < 0 OR _instant_pct > 100) THEN
    RAISE EXCEPTION 'invalid pct';
  END IF;
  PERFORM public.recalc_seller_trust(_user_id);
  UPDATE public.seller_trust
     SET manual_override_pct = _instant_pct,
         frozen = COALESCE(_frozen, frozen),
         updated_at = now()
   WHERE user_id = _user_id
   RETURNING * INTO _row;

  INSERT INTO public.balance_audit_log(user_id, event_type, delta_cents, actor_id, metadata)
  VALUES (_user_id, 'admin_override_trust', 0, auth.uid(),
          jsonb_build_object('instant_pct', _instant_pct, 'frozen', _frozen, 'reason', _reason));
  RETURN _row;
END $function$

CREATE OR REPLACE FUNCTION public.admin_recanonicalize_identity(_actor uuid, _id uuid, _new_fingerprint text, _new_language text, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  existing uuid;
  old_fp text;
  old_lang text;
BEGIN
  IF NOT public.has_role(_actor, 'admin') THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;
  IF _id IS NULL OR NOT EXISTS (SELECT 1 FROM public.card_identities WHERE id = _id) THEN
    RAISE EXCEPTION 'Identity not found';
  END IF;
  IF _new_fingerprint IS NULL OR _new_fingerprint !~ '^[0-9a-f]{32}$' THEN
    RAISE EXCEPTION 'Invalid fingerprint';
  END IF;

  SELECT fingerprint, language INTO old_fp, old_lang FROM public.card_identities WHERE id = _id;

  SELECT id INTO existing
  FROM public.card_identities
  WHERE fingerprint = _new_fingerprint AND id <> _id
  LIMIT 1;

  IF existing IS NOT NULL THEN
    PERFORM public._merge_identity_refs(existing, _id);
    INSERT INTO public.admin_action_log (admin_id, action, target_table, target_id, before_state, after_state, reason)
    VALUES (_actor, 'identity_recanonicalize_merge', 'card_identities', existing,
            jsonb_build_object('id', _id, 'fingerprint', old_fp, 'language', old_lang),
            jsonb_build_object('survivor', existing, 'fingerprint', _new_fingerprint),
            _reason);
    RETURN jsonb_build_object('result', 'merged', 'survivor', existing);
  END IF;

  UPDATE public.card_identities
  SET fingerprint = _new_fingerprint, language = _new_language
  WHERE id = _id;

  INSERT INTO public.admin_action_log (admin_id, action, target_table, target_id, before_state, after_state, reason)
  VALUES (_actor, 'identity_recanonicalize', 'card_identities', _id,
          jsonb_build_object('fingerprint', old_fp, 'language', old_lang),
          jsonb_build_object('fingerprint', _new_fingerprint, 'language', _new_language),
          _reason);

  RETURN jsonb_build_object('result', 'updated', 'id', _id);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_remove_role(_target_user uuid, _role app_role)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _caller uuid := auth.uid();
BEGIN
  IF _caller IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF _role = 'owner' THEN RAISE EXCEPTION 'Owner role cannot be removed'; END IF;
  IF public.has_role(_caller, 'owner') THEN
    NULL;
  ELSIF public.has_role(_caller, 'admin') THEN
    IF _role = 'admin' THEN RAISE EXCEPTION 'Only the owner can remove admin'; END IF;
  ELSE
    RAISE EXCEPTION 'Insufficient permissions';
  END IF;
  DELETE FROM public.user_roles WHERE user_id = _target_user AND role = _role;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_replay_finalize(_stream_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _caller uuid := auth.uid();
BEGIN
  IF _caller IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT (public.has_role(_caller,'admin') OR public.has_role(_caller,'owner')) THEN
    RAISE EXCEPTION 'Insufficient permissions';
  END IF;
  -- Force ends_at into the past so finalize is permitted
  UPDATE public.live_streams SET ends_at = LEAST(ends_at, now() - interval '1 second')
   WHERE id = _stream_id AND ends_at IS NOT NULL;
  RETURN public.finalize_auction_round(_stream_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_run_financial_reconciliation(_since timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS TABLE(scanned_orders bigint, missing_commission bigint, missing_shipping_margin bigint, payout_drift bigint, new_alerts bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM _assert_owner();
  RETURN QUERY SELECT * FROM public.run_financial_reconciliation(
    COALESCE(_since, now() - interval '7 days')
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_shipping_margin(_since timestamp with time zone DEFAULT NULL::timestamp with time zone, _until timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS TABLE(shipping_charged_cents bigint, label_cost_cents bigint, shipping_gross_margin_cents bigint, adjustment_fees_cents bigint, adjustment_losses_cents bigint, net_shipping_margin_cents bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _charged bigint;
  _label bigint;
  _adj_fees bigint;
  _adj_losses bigint;
BEGIN
  PERFORM _assert_owner();

  SELECT
    COALESCE(SUM((COALESCE(o.shipping_amount, 0) * 100)::bigint), 0)::bigint,
    COALESCE(SUM(COALESCE(o.label_cost_cents, 0)), 0)::bigint
  INTO _charged, _label
  FROM public.orders o
  WHERE o.payment_status = 'paid'
    AND (_since IS NULL OR o.created_at >= _since)
    AND (_until IS NULL OR o.created_at < _until);

  SELECT COALESCE(SUM(pr.amount_cents), 0)::bigint
  INTO _adj_fees
  FROM public.platform_revenue pr
  WHERE pr.kind = 'shipping_adjustment_fee'
    AND pr.amount_cents > 0
    AND (_since IS NULL OR pr.created_at >= _since)
    AND (_until IS NULL OR pr.created_at < _until);

  SELECT COALESCE(SUM(pr.amount_cents), 0)::bigint
  INTO _adj_losses
  FROM public.platform_revenue pr
  WHERE pr.kind = 'shipping_adjustment_fee'
    AND pr.amount_cents < 0
    AND (_since IS NULL OR pr.created_at >= _since)
    AND (_until IS NULL OR pr.created_at < _until);

  shipping_charged_cents := _charged;
  label_cost_cents := _label;
  shipping_gross_margin_cents := _charged - _label;
  adjustment_fees_cents := _adj_fees;
  adjustment_losses_cents := _adj_losses;
  net_shipping_margin_cents := (_charged - _label) + _adj_fees + _adj_losses;
  RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_waive_buyer_restriction(_buyer uuid, _notes text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _c uuid := auth.uid();
BEGIN
  IF NOT (public.has_role(_c,'admin') OR public.has_role(_c,'owner') OR public.has_role(_c,'moderator')) THEN RAISE EXCEPTION 'Insufficient permissions'; END IF;
  UPDATE public.profiles SET bid_restricted_until=NULL, bid_restricted_reason=NULL, unpaid_strikes=0 WHERE id=_buyer;
  UPDATE public.buyer_review_queue SET status='waived', resolved_by=_c, resolved_at=now(), resolution_notes=_notes WHERE buyer_id=_buyer AND status='pending';
  INSERT INTO public.notifications (user_id, sender_id, type, body, link)
  VALUES (_buyer, _c, 'account_restored', '✅ Your account restriction has been lifted. You can bid again.', '/');
END $function$

CREATE OR REPLACE FUNCTION public.append_dispute_message(_dispute_id uuid, _body text, _username text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  d record;
  is_admin boolean;
  role_label text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF _body IS NULL OR length(btrim(_body)) = 0 THEN
    RAISE EXCEPTION 'Message body required';
  END IF;
  IF length(_body) > 2000 THEN
    RAISE EXCEPTION 'Message too long';
  END IF;

  SELECT * INTO d FROM public.disputes WHERE id = _dispute_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Dispute not found'; END IF;

  is_admin := public.has_role(auth.uid(), 'admin'::app_role)
           OR public.has_role(auth.uid(), 'owner'::app_role);

  IF NOT (is_admin OR auth.uid() = d.reporter_id OR auth.uid() = d.reported_user_id) THEN
    RAISE EXCEPTION 'Not allowed';
  END IF;

  IF is_admin THEN role_label := 'admin';
  ELSIF auth.uid() = d.reporter_id THEN role_label := 'reporter';
  ELSE role_label := 'reported';
  END IF;

  UPDATE public.disputes
  SET messages = COALESCE(messages, '[]'::jsonb) || jsonb_build_array(
        jsonb_build_object(
          'user_id', auth.uid(),
          'username', COALESCE(_username, 'user'),
          'role', role_label,
          'body', btrim(_body),
          'at', now()
        )
      ),
      updated_at = now()
  WHERE id = _dispute_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_ai_shipment_scan(_code text, _kind text DEFAULT 'photo'::text, _suggested_status text DEFAULT 'ready_for_dropoff'::text, _carrier text DEFAULT NULL::text, _confidence numeric DEFAULT NULL::numeric, _metadata jsonb DEFAULT NULL::jsonb)
 RETURNS TABLE(order_id uuid, prev_status text, new_status text, result text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order_id uuid; v_seller uuid; v_prev text; v_new text; v_rank int; v_prev_rank int;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authorized'; END IF;

  -- Normalize status
  IF _suggested_status NOT IN ('label_created','ready_for_dropoff','shipped','delivered') THEN
    _suggested_status := 'ready_for_dropoff';
  END IF;

  -- Try exact tracking number match
  SELECT o.id, o.seller_id, o.prep_status
    INTO v_order_id, v_seller, v_prev
    FROM public.orders o
    WHERE o.tracking_number = _code
    ORDER BY o.created_at DESC LIMIT 1;

  -- Fallback: prefix match for partial OCR reads (>= 10 chars)
  IF v_order_id IS NULL AND length(_code) >= 10 THEN
    SELECT o.id, o.seller_id, o.prep_status
      INTO v_order_id, v_seller, v_prev
      FROM public.orders o
      WHERE o.tracking_number IS NOT NULL
        AND (o.tracking_number ILIKE _code || '%' OR _code ILIKE o.tracking_number || '%')
        AND o.seller_id = auth.uid()
      ORDER BY o.created_at DESC LIMIT 1;
  END IF;

  IF v_order_id IS NULL THEN
    INSERT INTO public.shipping_scans(order_id, scanned_by, code, kind, result, carrier, suggested_status, ai_confidence, ai_metadata)
      VALUES (NULL, auth.uid(), _code, _kind, 'unmatched', _carrier, _suggested_status, _confidence, _metadata);
    order_id := NULL; prev_status := NULL; new_status := NULL; result := 'unmatched';
    RETURN NEXT; RETURN;
  END IF;

  IF v_seller <> auth.uid() THEN
    INSERT INTO public.shipping_scans(order_id, scanned_by, code, kind, result, carrier, suggested_status, ai_confidence, ai_metadata)
      VALUES (v_order_id, auth.uid(), _code, _kind, 'mismatch', _carrier, _suggested_status, _confidence, _metadata);
    order_id := v_order_id; prev_status := v_prev; new_status := v_prev; result := 'mismatch';
    RETURN NEXT; RETURN;
  END IF;

  -- Never downgrade. Rank statuses.
  v_prev_rank := CASE COALESCE(v_prev,'label_pending')
    WHEN 'label_pending' THEN 0 WHEN 'label_created' THEN 1
    WHEN 'prepared' THEN 2 WHEN 'packed' THEN 3
    WHEN 'ready_for_dropoff' THEN 4 WHEN 'shipped' THEN 5
    WHEN 'delivered' THEN 6 ELSE 0 END;
  v_rank := CASE _suggested_status
    WHEN 'label_created' THEN 1 WHEN 'ready_for_dropoff' THEN 4
    WHEN 'shipped' THEN 5 WHEN 'delivered' THEN 6 ELSE 4 END;
  v_new := CASE WHEN v_rank > v_prev_rank THEN _suggested_status ELSE v_prev END;

  UPDATE public.orders
    SET prep_status = v_new,
        tracking_number = COALESCE(tracking_number, _code),
        carrier = COALESCE(carrier, _carrier),
        packed_at = COALESCE(packed_at, CASE WHEN v_new IN ('packed','ready_for_dropoff','shipped','delivered') THEN now() END),
        ready_at = COALESCE(ready_at, CASE WHEN v_new IN ('ready_for_dropoff','shipped','delivered') THEN now() END),
        dropoff_scanned_at = COALESCE(dropoff_scanned_at, CASE WHEN v_new IN ('shipped','delivered') THEN now() END),
        shipped_at = COALESCE(shipped_at, CASE WHEN v_new IN ('shipped','delivered') THEN now() END),
        delivered_at = COALESCE(delivered_at, CASE WHEN v_new = 'delivered' THEN now() END)
    WHERE id = v_order_id;

  INSERT INTO public.shipping_scans(order_id, scanned_by, code, kind, result, prev_status, new_status, carrier, suggested_status, ai_confidence, ai_metadata)
    VALUES (v_order_id, auth.uid(), _code, _kind, 'matched', v_prev, v_new, _carrier, _suggested_status, _confidence, _metadata);

  order_id := v_order_id; prev_status := v_prev; new_status := v_new; result := 'matched';
  RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_hold_recovery(_user_id uuid, _gross_cents bigint, _source text DEFAULT 'payout'::text, _reference_id text DEFAULT NULL::text)
 RETURNS hold_recoveries
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_hold public.account_holds;
  v_owed bigint := 0;
  v_deduct bigint := 0;
  v_net bigint := _gross_cents;
  v_remaining bigint := 0;
  v_rec public.hold_recoveries;
BEGIN
  IF _gross_cents <= 0 THEN
    RAISE EXCEPTION 'gross_cents must be positive';
  END IF;

  SELECT * INTO v_hold FROM public.account_holds
    WHERE user_id = _user_id AND status = 'active'
    FOR UPDATE;

  IF FOUND THEN
    v_owed := v_hold.balance_owed_cents;
    v_deduct := LEAST(v_owed, _gross_cents);
    v_net := _gross_cents - v_deduct;
    v_remaining := v_owed - v_deduct;

    UPDATE public.account_holds
      SET balance_owed_cents = v_remaining
      WHERE id = v_hold.id;
  END IF;

  -- Credit net to the seller balance (deducted portion offsets the negative)
  UPDATE public.profiles
    SET balance_cents = balance_cents + _gross_cents - v_deduct + v_deduct
    WHERE id = _user_id;
  -- Note: the line above credits gross-deduct (net) to balance; the deducted
  -- portion was already accounted as debt in balance_cents, so we add it back
  -- to bring the balance toward zero. Net effect: balance += gross.
  -- If the seller's balance is now >= 0 and a hold is active, auto-clear it.
  IF v_hold.id IS NOT NULL AND v_remaining <= 0 THEN
    UPDATE public.account_holds
      SET status = 'cleared',
          cleared_at = now(),
          notes = COALESCE(notes || E'\n', '') || 'Auto-cleared via recovery'
      WHERE id = v_hold.id;
    UPDATE public.profiles SET payout_hold = false WHERE id = _user_id;
  END IF;

  INSERT INTO public.hold_recoveries
    (user_id, hold_id, source, reference_id, gross_cents, deducted_cents, net_released_cents, remaining_owed_cents)
    VALUES (_user_id, v_hold.id, _source, _reference_id, _gross_cents, v_deduct, v_net, v_remaining)
    RETURNING * INTO v_rec;

  RETURN v_rec;
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_stream_shipping_cap()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  stream_ship  numeric;
  paid_so_far  numeric;
  headroom     numeric;
  cap          numeric := 7.00;
BEGIN
  IF NEW.stream_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Only cap US-bound shipments.
  IF COALESCE(UPPER(NEW.ship_country), 'US') <> 'US' THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(shipping_price, 0) INTO stream_ship
    FROM public.live_streams WHERE id = NEW.stream_id;

  IF stream_ship IS NULL THEN
    stream_ship := COALESCE(NEW.shipping_amount, 0);
  END IF;

  SELECT COALESCE(SUM(shipping_amount), 0) INTO paid_so_far
    FROM public.orders
   WHERE stream_id    = NEW.stream_id
     AND buyer_id     = NEW.buyer_id
     AND payment_status IN ('paid','processing','awaiting_payment','failed')
     AND id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid);

  headroom := GREATEST(cap - paid_so_far, 0);

  IF headroom <= 0 THEN
    NEW.shipping_amount := 0;
  ELSE
    NEW.shipping_amount := LEAST(stream_ship, headroom);
  END IF;

  RETURN NEW;
END;
$function$

