CREATE OR REPLACE FUNCTION public.assert_order_payout_consistent()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _subtotal numeric;
  _commission numeric;
  _payout numeric;
  _drift numeric;
  _tax numeric;
  _charged numeric;
BEGIN
  IF NEW.payment_status <> 'paid' THEN
    RETURN NEW;
  END IF;
  IF NEW.commission_amount IS NULL OR NEW.seller_payout_amount IS NULL THEN
    RETURN NEW;
  END IF;

  _subtotal := COALESCE(NEW.amount, 0) - COALESCE(NEW.shipping_amount, 0);
  _commission := COALESCE(NEW.commission_amount, 0);
  _payout := COALESCE(NEW.seller_payout_amount, 0);
  _tax := COALESCE(NEW.tax_cents, 0)::numeric / 100;
  _charged := COALESCE(NEW.final_charged_total_cents, 0)::numeric / 100;
  _drift := ABS((_commission + _payout) - _subtotal);

  IF _drift > 0.02 THEN
    RAISE EXCEPTION 'order % payout inconsistent: subtotal=% commission=% payout=% drift=%',
      NEW.id, _subtotal, _commission, _payout, _drift;
  END IF;

  IF _payout > _subtotal + 0.02 THEN
    RAISE EXCEPTION 'order % seller payout (%) exceeds subtotal (%)', NEW.id, _payout, _subtotal;
  END IF;

  IF _tax > 0 AND COALESCE(NEW.tax_jurisdiction, '') = '' THEN
    RAISE EXCEPTION 'order % has tax without jurisdiction', NEW.id;
  END IF;

  IF _charged > 0 AND _charged + 0.02 < COALESCE(NEW.amount, 0) + _tax THEN
    RAISE EXCEPTION 'order % charged total (%) is below order amount plus tax (%)',
      NEW.id, _charged, COALESCE(NEW.amount, 0) + _tax;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_payout_within_available_balance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_available bigint;
  v_unscanned_count int;
  v_active_hold int;
BEGIN
  -- Block if active account hold
  SELECT COUNT(*) INTO v_active_hold
  FROM public.account_holds
  WHERE user_id = NEW.user_id AND status = 'active';
  IF v_active_hold > 0 THEN
    RAISE EXCEPTION 'Payouts are paused: your account has an active hold. Contact support.';
  END IF;

  -- Block if any label-created order over 5 days without scan
  SELECT COUNT(*) INTO v_unscanned_count
  FROM public.orders
  WHERE seller_id = NEW.user_id
    AND shipping_status = 'label_created'
    AND first_scan_at IS NULL
    AND label_purchased_at < now() - interval '5 days';
  IF v_unscanned_count > 0 THEN
    RAISE EXCEPTION 'You have % shipment(s) where the carrier never scanned the label. Drop them off or void them before requesting payout.', v_unscanned_count;
  END IF;

  -- Check available balance
  SELECT COALESCE(available_cents, 0) INTO v_available
  FROM public.v_seller_available_balance
  WHERE seller_id = NEW.user_id;

  IF NEW.amount_cents > COALESCE(v_available, 0) THEN
    RAISE EXCEPTION 'Requested % cents exceeds available balance % cents. Funds are held until carrier confirmation.', NEW.amount_cents, COALESCE(v_available,0);
  END IF;

  RETURN NEW;
END$function$

