CREATE OR REPLACE FUNCTION public.auto_unblock_on_order_cancel()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now_cancelled boolean;
  v_was_cancelled boolean;
  v_remaining_unpaid int;
BEGIN
  -- Treat as "cancelled" if status is cancelled OR payment_status is cancelled/refunded.
  v_now_cancelled := (NEW.status IN ('cancelled','canceled','refunded'))
                  OR (NEW.payment_status IN ('cancelled','canceled','refunded'));
  v_was_cancelled := (OLD.status IN ('cancelled','canceled','refunded'))
                  OR (OLD.payment_status IN ('cancelled','canceled','refunded'));

  IF v_now_cancelled AND NOT v_was_cancelled AND NEW.stream_id IS NOT NULL THEN
    -- Count remaining unpaid/failed orders for this buyer in this stream.
    SELECT COUNT(*) INTO v_remaining_unpaid
    FROM public.orders
    WHERE stream_id = NEW.stream_id
      AND buyer_id = NEW.buyer_id
      AND id <> NEW.id
      AND payment_status IN ('failed','chargeback','awaiting_payment','processing','pending');

    IF v_remaining_unpaid = 0 THEN
      DELETE FROM public.live_bid_blocks
      WHERE stream_id = NEW.stream_id
        AND user_id = NEW.buyer_id;

      -- Notify the buyer that they can resume bidding.
      INSERT INTO public.notifications (user_id, type, body, link)
      VALUES (
        NEW.buyer_id,
        'payment',
        'Your unpaid order was cancelled by the host. You can place bids again.',
        '/live/' || NEW.stream_id::text
      );
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.award_credits(_amount bigint, _source text DEFAULT 'reward_claim'::text, _ref_id text DEFAULT NULL::text, _description text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _new_balance bigint;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF _amount = 0 THEN
    SELECT balance INTO _new_balance FROM public.credit_wallets WHERE user_id = _uid;
    RETURN COALESCE(_new_balance, 0);
  END IF;

  INSERT INTO public.credit_wallets (user_id, balance, lifetime_earned, lifetime_spent)
  VALUES (
    _uid,
    GREATEST(0, _amount),
    GREATEST(0, _amount),
    GREATEST(0, -_amount)
  )
  ON CONFLICT (user_id) DO UPDATE SET
    balance = public.credit_wallets.balance + _amount,
    lifetime_earned = public.credit_wallets.lifetime_earned + GREATEST(0, _amount),
    lifetime_spent = public.credit_wallets.lifetime_spent + GREATEST(0, -_amount),
    updated_at = now()
  RETURNING balance INTO _new_balance;

  INSERT INTO public.credit_transactions (user_id, amount, balance_after, source, ref_id, description)
  VALUES (_uid, _amount, _new_balance, _source, _ref_id, _description);

  RETURN _new_balance;
END;
$function$

CREATE OR REPLACE FUNCTION public.award_xp(_amount integer, _reason text, _ref_id text DEFAULT NULL::text)
 RETURNS TABLE(new_xp bigint, new_level integer, leveled_up boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid UUID := auth.uid();
  prev_level INT;
  next_level INT;
  next_xp BIGINT;
BEGIN
  IF uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF _amount IS NULL OR _amount = 0 THEN
    RAISE EXCEPTION 'Invalid xp amount';
  END IF;

  INSERT INTO public.user_progression (user_id, xp, lifetime_xp, level)
  VALUES (uid, GREATEST(0, _amount), GREATEST(0, _amount), 1)
  ON CONFLICT (user_id) DO UPDATE
    SET xp = GREATEST(0, public.user_progression.xp + _amount),
        lifetime_xp = public.user_progression.lifetime_xp + GREATEST(0, _amount),
        updated_at = now()
  RETURNING level, xp INTO prev_level, next_xp;

  next_level := public.xp_to_level(next_xp);
  IF next_level <> prev_level THEN
    UPDATE public.user_progression SET level = next_level WHERE user_id = uid;
  END IF;

  INSERT INTO public.xp_events (user_id, amount, reason, ref_id)
  VALUES (uid, _amount, _reason, _ref_id);

  RETURN QUERY SELECT next_xp, next_level, (next_level > prev_level);
END;
$function$

CREATE OR REPLACE FUNCTION public.bump_combo_streak(_stream_id uuid)
 RETURNS TABLE(combo_count integer, best_combo integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_prev int := 0; v_last timestamptz; v_new int; v_best int := 0;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authorized'; END IF;
  SELECT cs.combo_count, cs.last_bid_at, cs.best_combo
    INTO v_prev, v_last, v_best
    FROM public.user_combo_streaks cs
    WHERE cs.user_id = v_uid AND cs.stream_id = _stream_id;

  IF v_last IS NULL OR (now() - v_last) > interval '20 seconds' THEN
    v_new := 1;
  ELSE
    v_new := COALESCE(v_prev,0) + 1;
  END IF;

  v_best := GREATEST(COALESCE(v_best,0), v_new);

  INSERT INTO public.user_combo_streaks(user_id, stream_id, combo_count, best_combo, last_bid_at)
    VALUES (v_uid, _stream_id, v_new, v_best, now())
    ON CONFLICT (user_id, stream_id) DO UPDATE
      SET combo_count = EXCLUDED.combo_count,
          best_combo = GREATEST(public.user_combo_streaks.best_combo, EXCLUDED.combo_count),
          last_bid_at = now();

  combo_count := v_new; best_combo := v_best;
  RETURN NEXT;
END;
$function$

