CREATE OR REPLACE FUNCTION public.bump_quest_progress(_slug text, _delta integer DEFAULT 1)
 RETURNS TABLE(progress integer, target integer, completed boolean, xp_awarded integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid UUID := auth.uid();
  q RECORD;
  pkey TEXT;
  row_id UUID;
  new_progress INT;
  was_complete BOOLEAN;
  awarded INT := 0;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;

  SELECT * INTO q FROM public.daily_quests WHERE slug = _slug AND is_active;
  IF q IS NULL THEN RETURN; END IF;

  pkey := CASE WHEN q.kind = 'weekly'
               THEN to_char(now(), 'IYYY"-W"IW')
               ELSE to_char(CURRENT_DATE, 'YYYY-MM-DD') END;

  INSERT INTO public.user_quest_progress (user_id, quest_slug, period_key, progress)
  VALUES (uid, _slug, pkey, GREATEST(0, _delta))
  ON CONFLICT (user_id, quest_slug, period_key) DO UPDATE
    SET progress = public.user_quest_progress.progress + _delta,
        updated_at = now()
  RETURNING id, progress, (completed_at IS NOT NULL) INTO row_id, new_progress, was_complete;

  IF NOT was_complete AND new_progress >= q.target THEN
    UPDATE public.user_quest_progress
       SET completed_at = now(), claimed_at = now()
     WHERE id = row_id;
    PERFORM public.award_xp(q.xp_reward, 'quest:' || _slug, pkey);
    awarded := q.xp_reward;
  END IF;

  RETURN QUERY SELECT new_progress, q.target, (new_progress >= q.target), awarded;
END;
$function$

CREATE OR REPLACE FUNCTION public.buyer_can_purchase(_user_id uuid, _amount_cents integer DEFAULT NULL::integer)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r record;
BEGIN
  FOR r IN SELECT * FROM public.buyer_active_restrictions(_user_id) LOOP
    IF r.kind IN ('frozen','purchase_block') THEN
      RETURN false;
    END IF;
    IF r.kind = 'bid_limit' AND _amount_cents IS NOT NULL
       AND r.cents_limit IS NOT NULL AND _amount_cents > r.cents_limit THEN
      RETURN false;
    END IF;
  END LOOP;
  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.change_shop_name(_new_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _old text;
  _changes int;
  _pending int;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF _new_name IS NULL OR length(btrim(_new_name)) < 3 OR length(_new_name) > 30 THEN
    RAISE EXCEPTION 'Shop name must be 3-30 characters';
  END IF;
  IF _new_name !~ '^[A-Za-z0-9_ -]+$' THEN
    RAISE EXCEPTION 'Shop name may only contain letters, numbers, spaces, _ and -';
  END IF;

  SELECT shop_name, shop_name_changes INTO _old, _changes
    FROM public.profiles WHERE id = _uid;

  IF _changes >= 1 AND _old IS NOT NULL THEN
    RAISE EXCEPTION 'Shop name can only be changed once';
  END IF;

  SELECT count(*) INTO _pending FROM public.orders
    WHERE seller_id = _uid AND status IN ('pending','shipped','disputed');
  IF _pending > 0 THEN
    RAISE EXCEPTION 'Finish your pending and undelivered orders before renaming your shop';
  END IF;

  INSERT INTO public.shop_name_history (user_id, old_name, new_name)
    VALUES (_uid, _old, _new_name);

  UPDATE public.profiles
    SET shop_name = _new_name,
        shop_name_changes = COALESCE(shop_name_changes, 0) + 1
    WHERE id = _uid;

  RETURN jsonb_build_object('ok', true, 'old', _old, 'new', _new_name);
END;
$function$

CREATE OR REPLACE FUNCTION public.chat_messages_validate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _is_staff boolean;
  _recent int;
  _profile_username text;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  _is_staff := public.is_stream_staff(NEW.stream_id, _uid)
            OR public.has_role(_uid,'admin') OR public.has_role(_uid,'owner') OR public.has_role(_uid,'moderator');

  IF NOT _is_staff THEN
    NEW.user_id := _uid;
    NEW.is_system := false;
    NEW.is_announcement := false;
    NEW.is_hype := false;
    -- Force username from caller's profile to prevent impersonation
    SELECT username INTO _profile_username FROM public.profiles WHERE id = _uid;
    IF _profile_username IS NULL THEN
      RAISE EXCEPTION 'Profile required to chat';
    END IF;
    NEW.username := _profile_username;
  ELSE
    IF NEW.user_id IS NOT NULL AND NEW.user_id <> _uid THEN
      RAISE EXCEPTION 'Cannot post as another user';
    END IF;
    -- For staff posting as themselves (non-system), enforce their own username
    IF NEW.user_id = _uid AND NOT NEW.is_system THEN
      SELECT username INTO _profile_username FROM public.profiles WHERE id = _uid;
      IF _profile_username IS NOT NULL THEN
        NEW.username := _profile_username;
      END IF;
    END IF;
  END IF;

  IF NEW.content IS NULL OR length(btrim(NEW.content)) = 0 OR length(NEW.content) > 500 THEN
    RAISE EXCEPTION 'Chat message must be 1..500 chars';
  END IF;

  SELECT count(*) INTO _recent FROM public.chat_messages
   WHERE user_id = _uid AND stream_id = NEW.stream_id AND created_at > now() - interval '1 minute';
  IF _recent >= 30 THEN
    RAISE EXCEPTION 'Slow down — chat rate limit reached';
  END IF;

  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.check_combo_achievements()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.current_streak >= 5 THEN PERFORM public.unlock_achievement(NEW.user_id, 'combo_5'); END IF;
  IF NEW.current_streak >= 10 THEN PERFORM public.unlock_achievement(NEW.user_id, 'combo_10'); END IF;
  IF NEW.current_streak >= 25 THEN PERFORM public.unlock_achievement(NEW.user_id, 'combo_25'); END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_shipping_achievements()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _count int;
BEGIN
  IF NEW.scan_type IS DISTINCT FROM 'packed' THEN RETURN NEW; END IF;

  SELECT count(*) INTO _count
  FROM public.shipping_scans
  WHERE seller_id = NEW.seller_id AND scan_type = 'packed';

  IF _count >= 1 THEN PERFORM public.unlock_achievement(NEW.seller_id, 'ship_first'); END IF;
  IF _count >= 10 THEN PERFORM public.unlock_achievement(NEW.seller_id, 'ship_10'); END IF;
  IF _count >= 50 THEN PERFORM public.unlock_achievement(NEW.seller_id, 'ship_50'); END IF;
  IF _count >= 250 THEN PERFORM public.unlock_achievement(NEW.seller_id, 'ship_250'); END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_break_slots(_stream_id uuid, _slot_numbers integer[])
 RETURNS TABLE(order_id uuid, claimed_count integer, total_amount numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _buyer uuid := auth.uid();
  _seller uuid;
  _stream_title text;
  _slot_count integer;
  _price numeric;
  _prefix text;
  _characters jsonb;
  _item_image text;
  _username text;
  _full_name text;
  _address text;
  _city text;
  _state text;
  _zip text;
  _country text;
  _nums integer[];
  _labels text[];
  _order_id uuid;
BEGIN
  IF _buyer IS NULL THEN
    RAISE EXCEPTION 'You must be signed in to claim a character';
  END IF;

  SELECT ls.seller_id,
         ls.title,
         ls.break_slot_count,
         COALESCE(ls.break_slot_price, 10),
         ls.break_slot_prefix,
         ls.break_characters,
         COALESCE(ls.item_image_url, ls.thumbnail_url)
    INTO _seller, _stream_title, _slot_count, _price, _prefix, _characters, _item_image
  FROM public.live_streams ls
  WHERE ls.id = _stream_id
    AND ls.break_mode = 'open'
  FOR UPDATE;

  IF _seller IS NULL THEN
    RAISE EXCEPTION 'This break is not open';
  END IF;

  IF _seller = _buyer THEN
    RAISE EXCEPTION 'Host cannot claim their own break slots';
  END IF;

  SELECT array_agg(DISTINCT n ORDER BY n)
    INTO _nums
  FROM unnest(COALESCE(_slot_numbers, ARRAY[]::integer[])) AS n
  WHERE n BETWEEN 1 AND COALESCE(_slot_count, 0);

  IF _nums IS NULL OR array_length(_nums, 1) IS NULL THEN
    RAISE EXCEPTION 'Choose at least one available character';
  END IF;

  IF array_length(_nums, 1) > 10 THEN
    RAISE EXCEPTION 'Claim up to 10 characters at a time';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.break_slots bs
    WHERE bs.stream_id = _stream_id
      AND bs.slot_number = ANY(_nums)
  ) THEN
    RAISE EXCEPTION 'One of those characters was just claimed';
  END IF;

  SELECT COALESCE(p.username, 'buyer'),
         COALESCE(p.full_name, p.username, 'Buyer'),
         COALESCE(p.address_line1, ''),
         COALESCE(p.address_city, ''),
         COALESCE(p.address_state, ''),
         COALESCE(p.address_zip, ''),
         COALESCE(p.address_country, 'US')
    INTO _username, _full_name, _address, _city, _state, _zip, _country
  FROM public.profiles p
  WHERE p.id = _buyer;

  SELECT array_agg(
           COALESCE(NULLIF(_characters ->> (n - 1), ''), COALESCE(_prefix, '#') || n::text)
           ORDER BY n
         )
    INTO _labels
  FROM unnest(_nums) AS n;

  INSERT INTO public.orders (
    buyer_id,
    seller_id,
    title,
    description,
    amount,
    item_image_url,
    stream_id,
    status,
    payment_status,
    paid_at,
    ship_name,
    ship_address,
    ship_city,
    ship_state,
    ship_zip,
    ship_country
  ) VALUES (
    _buyer,
    _seller,
    'Mystery Break — ' || array_length(_nums, 1)::text || ' character' || CASE WHEN array_length(_nums, 1) = 1 THEN '' ELSE 's' END,
    'Mystery Break in ' || COALESCE(_stream_title, 'live stream') || ': ' || array_to_string(_labels, ', '),
    _price * array_length(_nums, 1),
    _item_image,
    _stream_id,
    'pending',
    'paid',
    now(),
    _full_name,
    _address,
    _city,
    _state,
    _zip,
    _country
  )
  RETURNING id INTO _order_id;

  INSERT INTO public.break_slots (
    stream_id,
    buyer_id,
    buyer_username,
    amount,
    slot_number,
    character_label,
    team_label,
    assigned_at,
    order_id
  )
  SELECT _stream_id,
         _buyer,
         _username,
         _price,
         n,
         COALESCE(NULLIF(_characters ->> (n - 1), ''), COALESCE(_prefix, '#') || n::text),
         COALESCE(NULLIF(_characters ->> (n - 1), ''), COALESCE(_prefix, '#') || n::text),
         now(),
         _order_id
  FROM unnest(_nums) AS n;

  order_id := _order_id;
  claimed_count := array_length(_nums, 1);
  total_amount := _price * claimed_count;
  RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_daily_login()
 RETURNS TABLE(streak integer, xp_awarded integer, already_claimed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid UUID := auth.uid();
  prev_date DATE;
  prev_streak INT := 0;
  new_streak INT := 1;
  reward INT;
BEGIN
  IF uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT last_login_date, login_streak
    INTO prev_date, prev_streak
  FROM public.user_progression WHERE user_id = uid;

  IF prev_date = CURRENT_DATE THEN
    RETURN QUERY SELECT prev_streak, 0, true;
    RETURN;
  END IF;

  IF prev_date = CURRENT_DATE - INTERVAL '1 day' THEN
    new_streak := COALESCE(prev_streak, 0) + 1;
  ELSE
    new_streak := 1;
  END IF;

  -- reward grows with streak, caps at 200xp
  reward := LEAST(200, 25 + (new_streak * 10));

  INSERT INTO public.user_progression (user_id, last_login_date, login_streak, longest_login_streak)
  VALUES (uid, CURRENT_DATE, new_streak, new_streak)
  ON CONFLICT (user_id) DO UPDATE
    SET last_login_date = CURRENT_DATE,
        login_streak = new_streak,
        longest_login_streak = GREATEST(public.user_progression.longest_login_streak, new_streak),
        updated_at = now();

  PERFORM public.award_xp(reward, 'daily_login', new_streak::text);

  RETURN QUERY SELECT new_streak, reward, false;
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_reward(_def_slug text, _context_key text DEFAULT ''::text, _context_label text DEFAULT NULL::text)
 RETURNS TABLE(granted boolean, credits integer, xp integer, badge_slug text, title text, description text, new_balance bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _def public.reward_definitions%ROWTYPE;
  _existing public.reward_claims%ROWTYPE;
  _bal bigint;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;

  SELECT * INTO _def FROM public.reward_definitions
    WHERE slug = _def_slug AND is_active = true;
  IF _def.id IS NULL THEN RAISE EXCEPTION 'Reward not found or inactive'; END IF;

  SELECT * INTO _existing FROM public.reward_claims
    WHERE user_id = _uid AND reward_def_id = _def.id
      AND context_key = COALESCE(_context_key, '');

  IF _existing.id IS NOT NULL AND _existing.status = 'claimed' THEN
    -- already claimed; no double grant
    SELECT balance INTO _bal FROM public.credit_wallets WHERE user_id = _uid;
    RETURN QUERY SELECT false, _def.credits, _def.xp, _def.badge_slug, _def.title, _def.description, COALESCE(_bal, 0);
    RETURN;
  END IF;

  -- upsert claim as claimed
  INSERT INTO public.reward_claims (
    user_id, reward_def_id, context_key, context_label,
    status, progress, target, unlocked_at, claimed_at
  ) VALUES (
    _uid, _def.id, COALESCE(_context_key, ''), _context_label,
    'claimed', 1, 1, now(), now()
  )
  ON CONFLICT (user_id, reward_def_id, context_key)
  DO UPDATE SET status = 'claimed', claimed_at = now(),
    unlocked_at = COALESCE(public.reward_claims.unlocked_at, now()),
    context_label = COALESCE(EXCLUDED.context_label, public.reward_claims.context_label),
    updated_at = now();

  -- grant credits
  IF _def.credits <> 0 THEN
    _bal := public.award_credits(_def.credits::bigint, 'reward_claim', _def.slug, _def.title);
  ELSE
    SELECT balance INTO _bal FROM public.credit_wallets WHERE user_id = _uid;
  END IF;

  -- grant XP
  IF _def.xp > 0 THEN
    PERFORM public.award_xp(_def.xp, 'reward', _def.slug);
  END IF;

  -- grant badge / cosmetic
  IF _def.badge_slug IS NOT NULL THEN
    INSERT INTO public.user_rewards (user_id, reward_slug)
    VALUES (_uid, _def.badge_slug)
    ON CONFLICT (user_id, reward_slug) DO NOTHING;
  END IF;

  RETURN QUERY SELECT true, _def.credits, _def.xp, _def.badge_slug, _def.title, _def.description, COALESCE(_bal, 0);
END;
$function$

CREATE OR REPLACE FUNCTION public.clear_hold_admin(_hold_id uuid, _override boolean DEFAULT false, _notes text DEFAULT NULL::text)
 RETURNS account_holds
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_hold public.account_holds;
  v_caller uuid := auth.uid();
BEGIN
  IF NOT (
    public.has_role(v_caller, 'admin') OR
    public.has_role(v_caller, 'owner') OR
    public.has_role(v_caller, 'moderator') OR
    public.has_role(v_caller, 'support')
  ) THEN RAISE EXCEPTION 'Only staff can clear holds'; END IF;

  UPDATE public.account_holds
  SET status = CASE WHEN _override THEN 'admin_override'::public.hold_status ELSE 'cleared'::public.hold_status END,
      cleared_at = now(),
      cleared_by = v_caller,
      notes = COALESCE(notes || E'\n', '') || COALESCE(_notes, '')
  WHERE id = _hold_id
  RETURNING * INTO v_hold;

  IF NOT EXISTS (SELECT 1 FROM public.account_holds WHERE user_id = v_hold.user_id AND status = 'active') THEN
    UPDATE public.profiles SET payout_hold = false WHERE id = v_hold.user_id;
  END IF;

  RETURN v_hold;
END;
$function$

CREATE OR REPLACE FUNCTION public.collab_invite_apply_accept()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE av text;
BEGIN
  IF NEW.status = 'accepted' AND COALESCE(OLD.status,'') <> 'accepted' THEN
    INSERT INTO public.stream_moderators (stream_id, host_id, mod_user_id, mod_username)
    VALUES (NEW.stream_id, NEW.host_id, NEW.invitee_id, NEW.invitee_username)
    ON CONFLICT DO NOTHING;
    SELECT avatar_url INTO av FROM public.profiles WHERE id = NEW.invitee_id;
    INSERT INTO public.stream_collab_participants (stream_id, user_id, username, avatar_url)
    VALUES (NEW.stream_id, NEW.invitee_id, NEW.invitee_username, av)
    ON CONFLICT DO NOTHING;
    NEW.responded_at := now();
  ELSIF NEW.status = 'declined' AND COALESCE(OLD.status,'') <> 'declined' THEN
    NEW.responded_at := now();
  END IF;
  RETURN NEW;
END;
$function$

