CREATE OR REPLACE FUNCTION public.compute_buyer_fee_cents(_buyer_id uuid, _stream_id uuid, _default_cents integer DEFAULT 123, _threshold integer DEFAULT 3)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  paid_count integer;
BEGIN
  IF _stream_id IS NULL THEN
    RETURN _default_cents;
  END IF;
  SELECT COUNT(*) INTO paid_count
  FROM public.orders
  WHERE buyer_id = _buyer_id
    AND stream_id = _stream_id
    AND payment_status = 'paid';
  IF paid_count >= _threshold THEN
    RETURN 0;
  END IF;
  RETURN _default_cents;
END;
$function$

CREATE OR REPLACE FUNCTION public.compute_platform_available()
 RETURNS TABLE(net_earnings_cents bigint, payouts_pending_cents bigint, payouts_completed_cents bigint, available_cents bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _net bigint;
  _pending bigint;
  _done bigint;
BEGIN
  PERFORM _assert_owner();

  SELECT COALESCE(SUM(amount_cents), 0) INTO _net FROM platform_revenue;
  SELECT COALESCE(SUM(amount_cents), 0) INTO _pending
    FROM platform_payouts WHERE status IN ('requested','processing');
  SELECT COALESCE(SUM(amount_cents), 0) INTO _done
    FROM platform_payouts WHERE status = 'completed';

  net_earnings_cents := _net;
  payouts_pending_cents := _pending;
  payouts_completed_cents := _done;
  available_cents := GREATEST(_net - _pending - _done, 0);
  RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION public.compute_seller_payable(_user_id uuid)
 RETURNS TABLE(available_cents bigint, pending_cents bigint, locked_cents bigint, in_flight_cents bigint, owed_cents bigint, payable_cents bigint, instant_pct integer, tier seller_trust_tier, frozen boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _trust public.seller_trust;
  _instant INTEGER;
  _delivered_net BIGINT := 0;
  _undelivered_net BIGINT := 0;
  _instant_from_pending BIGINT := 0;
  _locked BIGINT := 0;
  _inflight BIGINT := 0;
  _owed BIGINT := 0;
  _is_admin BOOLEAN := false;
BEGIN
  PERFORM public.recalc_seller_trust(_user_id);
  SELECT * INTO _trust FROM public.seller_trust WHERE user_id = _user_id;

  _is_admin := public.has_role(_user_id, 'owner') OR public.has_role(_user_id, 'admin');

  IF _is_admin THEN
    -- Owner/admin: full instant release unless an explicit manual override is set.
    _instant := COALESCE(_trust.manual_override_pct, 100);
  ELSE
    _instant := COALESCE(_trust.manual_override_pct, _trust.instant_release_pct);
  END IF;

  SELECT COALESCE(SUM(
    CASE WHEN seller_payout_amount IS NOT NULL THEN (seller_payout_amount * 100)::bigint
         ELSE (amount * (1 - COALESCE(commission_rate,0.05)) * 100)::bigint END
  ),0) INTO _delivered_net
  FROM public.orders
  WHERE seller_id = _user_id
    AND status = 'delivered'
    AND payment_status = 'paid'
    AND COALESCE(refunded_amount,0) = 0
    AND payout_held = false;

  SELECT COALESCE(SUM(
    CASE WHEN seller_payout_amount IS NOT NULL THEN (seller_payout_amount * 100)::bigint
         ELSE (amount * (1 - COALESCE(commission_rate,0.05)) * 100)::bigint END
  ),0) INTO _undelivered_net
  FROM public.orders
  WHERE seller_id = _user_id
    AND status IN ('pending','shipped')
    AND payment_status = 'paid'
    AND COALESCE(refunded_amount,0) = 0
    AND payout_held = false
    AND id NOT IN (SELECT order_id FROM public.payout_locks WHERE released_at IS NULL);

  _instant_from_pending := (_undelivered_net * _instant) / 100;

  SELECT COALESCE(SUM(amount_cents),0) INTO _locked
    FROM public.payout_locks WHERE user_id = _user_id AND released_at IS NULL;

  SELECT COALESCE(SUM(amount_cents),0) INTO _inflight
    FROM public.payout_requests
    WHERE user_id = _user_id AND status IN ('requested','processing');

  SELECT COALESCE(SUM(balance_owed_cents),0) INTO _owed
    FROM public.account_holds WHERE user_id = _user_id AND status = 'active';

  available_cents := _delivered_net + _instant_from_pending;
  pending_cents   := _undelivered_net - _instant_from_pending;
  locked_cents    := _locked;
  in_flight_cents := _inflight;
  owed_cents      := _owed;
  payable_cents   := GREATEST(0, available_cents - _inflight - _owed);
  IF COALESCE(_trust.frozen,false) THEN payable_cents := 0; END IF;
  instant_pct := _instant;
  tier := _trust.tier;
  frozen := COALESCE(_trust.frozen,false);
  RETURN NEXT;
END $function$

CREATE OR REPLACE FUNCTION public.create_giveaway_order(_giveaway_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _g giveaways%ROWTYPE;
  _stream_title text;
  _full_name text; _addr text; _city text; _state text; _zip text; _country text;
  _order_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;

  SELECT * INTO _g FROM giveaways WHERE id = _giveaway_id;
  IF _g IS NULL THEN RAISE EXCEPTION 'Giveaway not found'; END IF;
  IF _g.winner_id IS NULL THEN RAISE EXCEPTION 'No winner yet'; END IF;
  IF _g.seller_id <> auth.uid() AND _g.winner_id <> auth.uid() THEN
    RAISE EXCEPTION 'Only the host or winner can finalize this giveaway';
  END IF;

  SELECT id INTO _order_id FROM orders
  WHERE seller_id = _g.seller_id AND buyer_id = _g.winner_id
    AND stream_id = _g.stream_id
    AND title = 'Giveaway — ' || COALESCE(_g.prize_label, 'Prize')
  LIMIT 1;
  IF _order_id IS NOT NULL THEN
    UPDATE orders SET is_giveaway = true WHERE id = _order_id AND is_giveaway = false;
    RETURN _order_id;
  END IF;

  SELECT title INTO _stream_title FROM live_streams WHERE id = _g.stream_id;

  SELECT COALESCE(p.full_name, p.username, 'Winner'),
         COALESCE(p.address_line1, ''), COALESCE(p.address_city, ''),
         COALESCE(p.address_state, ''), COALESCE(p.address_zip, ''),
         COALESCE(p.address_country, 'US')
    INTO _full_name, _addr, _city, _state, _zip, _country
  FROM profiles p WHERE p.id = _g.winner_id;

  INSERT INTO orders (
    buyer_id, seller_id, title, description, amount,
    stream_id, status, payment_status, paid_at, is_giveaway,
    ship_name, ship_address, ship_city, ship_state, ship_zip, ship_country
  ) VALUES (
    _g.winner_id, _g.seller_id,
    'Giveaway — ' || COALESCE(_g.prize_label, 'Prize'),
    'Giveaway prize from ' || COALESCE(_stream_title, 'live stream') || ' (shipping covered by host)',
    0,
    _g.stream_id, 'pending', 'paid', now(), true,
    _full_name, _addr, _city, _state, _zip, _country
  ) RETURNING id INTO _order_id;

  RETURN _order_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.direct_messages_validate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _recent int;
  _cu text := current_user;
BEGIN
  -- Bypass for elevated server context (SECURITY DEFINER admin clients / cron).
  IF _cu IN ('postgres','supabase_admin','service_role','authenticator')
     AND current_setting('app.bypass_dm_check', true) = 'on' THEN
    RETURN NEW;
  END IF;

  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NEW.sender_id <> _uid THEN RAISE EXCEPTION 'Sender mismatch'; END IF;
  IF NEW.recipient_id = _uid THEN RAISE EXCEPTION 'Cannot message yourself'; END IF;
  IF NEW.content IS NULL OR length(btrim(NEW.content)) = 0 OR length(NEW.content) > 2000 THEN
    RAISE EXCEPTION 'Message must be 1..2000 chars';
  END IF;

  SELECT count(*) INTO _recent FROM public.direct_messages
    WHERE sender_id = _uid AND created_at > now() - interval '1 minute';
  IF _recent >= 60 THEN
    RAISE EXCEPTION 'Slow down — DM rate limit reached';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.email_queue_dispatch()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pgmq.q_auth_emails)
     AND NOT EXISTS (SELECT 1 FROM pgmq.q_transactional_emails) THEN
    BEGIN
      -- Serialize disarm against email_queue_wake on a shared advisory lock, then
      -- re-read under it: an enqueue racing the unschedule either committed (we
      -- see its row and leave the cron) or waits and re-arms after we commit.
      PERFORM pg_catalog.pg_advisory_xact_lock(7700000000000001);
      IF EXISTS (SELECT 1 FROM pgmq.q_auth_emails)
         OR EXISTS (SELECT 1 FROM pgmq.q_transactional_emails) THEN
        RETURN;
      END IF;
      PERFORM cron.unschedule('process-email-queue');
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'email_queue_dispatch: cron unschedule failed: %', SQLERRM;
    END;
    RETURN;
  END IF;

  IF (SELECT retry_after_until FROM public.email_send_state WHERE id = 1) > now() THEN
    RETURN;
  END IF;

  PERFORM net.http_post(
    url := 'https://project--c81c8301-d89c-4830-8ab7-06f678968bc1.lovable.app/lovable/email/queue/process',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Lovable-Context', 'cron',
      'Authorization', 'Bearer ' || (
        SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'email_queue_service_role_key'
      )
    ),
    body := '{}'::jsonb
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.email_queue_wake()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  -- Runs inside the enqueue transaction; the outer handler guarantees nothing
  -- below can roll back the customer's email. Shared advisory lock serializes
  -- arming against email_queue_dispatch's disarm.
  PERFORM pg_catalog.pg_advisory_xact_lock(7700000000000001);
  IF NOT EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'process-email-queue') THEN
    BEGIN
      PERFORM cron.schedule('process-email-queue', '5 seconds', $cron$ SELECT public.email_queue_dispatch(); $cron$);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'email_queue_wake: cron schedule failed: %', SQLERRM;
    END;
  END IF;

  BEGIN
    PERFORM net.http_post(
      url := 'https://project--c81c8301-d89c-4830-8ab7-06f678968bc1.lovable.app/lovable/email/queue/process',
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Lovable-Context', 'cron',
        'Authorization', 'Bearer ' || (
          SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'email_queue_service_role_key'
        )
      ),
      body := '{}'::jsonb
    );
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'email_queue_wake failed (enqueue preserved): %', SQLERRM;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_late_shipments()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _stage_a int := 0; _stage_b int := 0; _stage_c int := 0; _stage_d int := 0;
  _o record;
  _b6  timestamptz;
  _b9  timestamptz;
  _b14 timestamptz;
BEGIN
  FOR _o IN
    SELECT id, seller_id, buyer_id, paid_at, shipping_due_at, ship_reminder_count, last_ship_reminder_at, title
      FROM public.orders
     WHERE payment_status = 'paid'
       AND status = 'pending'
       AND shipping_due_at IS NOT NULL
       AND shipping_due_at <= now()
  LOOP
    _b6  := public.add_business_days(_o.paid_at, 6);
    _b9  := public.add_business_days(_o.paid_at, 9);
    _b14 := public.add_business_days(_o.paid_at, 14);

    -- Stage A: gentle reminder once per 24h until shipped
    IF _o.last_ship_reminder_at IS NULL OR _o.last_ship_reminder_at < now() - interval '24 hours' THEN
      INSERT INTO public.notifications (user_id, sender_id, type, body, link)
      VALUES (_o.seller_id, _o.seller_id, 'shipping',
        '⏰ Reminder: ship "' || _o.title || '" — buyer is waiting.', '/store');
      UPDATE public.orders
         SET last_ship_reminder_at = now(),
             ship_reminder_count   = ship_reminder_count + 1
       WHERE id = _o.id;
      _stage_a := _stage_a + 1;
    END IF;

    -- Stage B: 6 business days late → mark late + warn
    IF now() >= _b6 AND NOT _o.id IN (SELECT id FROM public.orders WHERE id = _o.id AND is_late_shipment) THEN
      UPDATE public.orders SET is_late_shipment = true WHERE id = _o.id AND NOT is_late_shipment;
      UPDATE public.profiles SET late_shipment_count = late_shipment_count + 1 WHERE id = _o.seller_id;
      INSERT INTO public.notifications (user_id, sender_id, type, body, link)
      VALUES (_o.seller_id, _o.seller_id, 'warning',
        '⚠️ "' || _o.title || '" is past the 3-day shipping window. Repeated delays affect your seller standing.', '/store');
      INSERT INTO public.notifications (user_id, sender_id, type, body, link)
      VALUES (_o.buyer_id, _o.seller_id, 'shipping',
        '⏳ Your order "' || _o.title || '" has not shipped yet. We''re following up with the seller.', '/orders');
      _stage_b := _stage_b + 1;
    END IF;

    -- Stage C: 9 business days → payout hold + visibility penalty
    IF now() >= _b9 AND NOT (SELECT payout_held FROM public.orders WHERE id = _o.id) THEN
      UPDATE public.orders SET payout_held = true WHERE id = _o.id;
      UPDATE public.profiles
         SET payout_hold = true,
             visibility_penalty_until = GREATEST(COALESCE(visibility_penalty_until, now()), now() + interval '14 days')
       WHERE id = _o.seller_id;
      INSERT INTO public.notifications (user_id, sender_id, type, body, link)
      VALUES (_o.seller_id, _o.seller_id, 'warning',
        '🚫 Payout for "' || _o.title || '" is on hold and your store visibility is reduced for 14 days. Ship or refund to resolve.', '/store');
      _stage_c := _stage_c + 1;
    END IF;

    -- Stage D: 14 business days → admin/audit flag (no auto-suspend)
    IF now() >= _b14 THEN
      INSERT INTO public.audit_logs (actor_id, action, target_type, target_id, meta)
      VALUES (NULL, 'shipping_severely_late', 'order', _o.id,
        jsonb_build_object('seller_id', _o.seller_id, 'paid_at', _o.paid_at, 'days_late_business', 14));
      _stage_d := _stage_d + 1;
    END IF;
  END LOOP;

  -- Auto-clear payout_hold + visibility penalty when seller has zero late open orders
  UPDATE public.profiles p
     SET payout_hold = false
   WHERE payout_hold = true
     AND NOT EXISTS (
       SELECT 1 FROM public.orders o
        WHERE o.seller_id = p.id AND o.payout_held = true AND o.status = 'pending'
     );

  RETURN jsonb_build_object(
    'reminders', _stage_a, 'warnings', _stage_b,
    'payout_holds', _stage_c, 'severe', _stage_d, 'ran_at', now()
  );
END $function$

CREATE OR REPLACE FUNCTION public.enforce_shoutout_cap()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE total numeric;
BEGIN
  SELECT COALESCE(SUM(amount), 0) INTO total
  FROM public.stream_shoutouts
  WHERE buyer_id = NEW.buyer_id AND stream_id = NEW.stream_id;
  IF (total + NEW.amount) > 50 THEN
    RAISE EXCEPTION 'Shout-out cap reached: $50 per stream (you have $% remaining)', GREATEST(0, 50 - total);
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enqueue_email(queue_name text, payload jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN pgmq.send(queue_name, payload);
EXCEPTION WHEN undefined_table THEN
  PERFORM pgmq.create(queue_name);
  RETURN pgmq.send(queue_name, payload);
END;
$function$

CREATE OR REPLACE FUNCTION public.error_logs_validate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _recent int;
BEGIN
  IF NEW.message IS NULL OR length(NEW.message)=0 THEN RAISE EXCEPTION 'message required'; END IF;
  IF length(NEW.message) > 2000 THEN NEW.message := left(NEW.message,2000); END IF;
  IF NEW.stack IS NOT NULL AND length(NEW.stack) > 8000 THEN NEW.stack := left(NEW.stack,8000); END IF;
  IF NEW.severity NOT IN ('info','warning','error','critical') THEN NEW.severity := 'error'; END IF;
  IF auth.uid() IS NOT NULL THEN
    SELECT count(*) INTO _recent FROM public.error_logs
      WHERE user_id = auth.uid() AND created_at > now() - interval '1 minute';
    IF _recent >= 120 THEN RAISE EXCEPTION 'error_logs rate limit'; END IF;
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.extend_flex_live_session(_stream_id uuid)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _until timestamptz;
  _minutes integer;
BEGIN
  SELECT COALESCE(c.flex_extension_minutes, 120)
  INTO _minutes
  FROM public.live_streams ls
  LEFT JOIN public.creator_stream_tiers c ON c.tier = ls.creator_tier
  WHERE ls.id = _stream_id AND ls.seller_id = auth.uid();

  IF _minutes IS NULL THEN
    RAISE EXCEPTION 'Stream not found';
  END IF;

  _until := now() + make_interval(mins => _minutes);

  UPDATE public.live_streams
  SET flex_extended_until = _until,
      stream_soft_reminder_at = now(),
      last_activity_at = now(),
      last_activity_type = 'flex_extended'
  WHERE id = _stream_id
    AND seller_id = auth.uid();

  RETURN _until;
END;
$function$

CREATE OR REPLACE FUNCTION public.finalize_auction_round(_stream_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _s public.live_streams%ROWTYPE;
  _caller uuid := auth.uid();
  _winner_id uuid;
  _winning_bid numeric;
  _winner_username text;
  _seller_username text;
  _label text;
  _item_name text;
  _next_round int;
  _existing_order uuid;
  _order_id uuid;
  _ship numeric := 0;
  _ship_for_this numeric := 0;
  _cap numeric;
  _p record;
BEGIN
  SELECT * INTO _s FROM public.live_streams WHERE id = _stream_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Stream not found';
  END IF;

  IF NOT (_caller = _s.seller_id OR _caller = _s.current_bidder_id OR public.has_role(_caller, 'admin') OR public.has_role(_caller, 'owner')) THEN
    RAISE EXCEPTION 'Only the seller, winning bidder, or admin can finalize';
  END IF;

  _winner_id := _s.current_bidder_id;
  _winning_bid := COALESCE(_s.current_bid, 0);
  _item_name := COALESCE(NULLIF(_s.current_item, ''), _s.title, 'Live auction item');
  _label := _item_name;
  _next_round := COALESCE(_s.round_number, 0) + 1;

  IF _s.winner_id IS NOT NULL
     AND _s.winner_id = _winner_id
     AND COALESCE(_s.winning_bid, 0) = _winning_bid THEN
    SELECT id INTO _existing_order FROM public.orders
      WHERE stream_id = _stream_id AND buyer_id = _winner_id
      ORDER BY created_at DESC LIMIT 1;
    RETURN jsonb_build_object('ok', true, 'already_finalized', true, 'order_id', _existing_order);
  END IF;

  IF _winner_id IS NULL THEN
    UPDATE public.live_streams SET ends_at = NULL WHERE id = _stream_id;
    INSERT INTO public.audit_logs (actor_id, action, target_type, target_id, meta)
      VALUES (_caller, 'auction_no_winner', 'live_stream', _stream_id,
              jsonb_build_object('round', _next_round));
    RETURN jsonb_build_object('ok', true, 'no_winner', true);
  END IF;

  SELECT username INTO _winner_username FROM public.profiles WHERE id = _winner_id;
  SELECT username INTO _seller_username FROM public.profiles WHERE id = _s.seller_id;

  SELECT shipping_cap INTO _cap FROM public.profiles WHERE id = _s.seller_id;
  _ship := COALESCE(_s.shipping_price, 0);
  _ship_for_this := CASE WHEN _cap IS NULL THEN _ship ELSE GREATEST(0, LEAST(_ship, _cap)) END;

  SELECT p.full_name, p.address_line1, p.address_city, p.address_state, p.address_zip, p.address_country
    INTO _p FROM public.profiles p WHERE p.id = _winner_id;

  INSERT INTO public.receipts (stream_id, buyer_id, seller_id, item_name, item_image_url, amount)
    VALUES (_stream_id, _winner_id, _s.seller_id, _label, _s.item_image_url, _winning_bid);

  BEGIN
    INSERT INTO public.orders (
      buyer_id, seller_id, title, description, amount, shipping_amount, item_image_url,
      stream_id, condition, status, payment_status,
      ship_name, ship_address, ship_city, ship_state, ship_zip, ship_country
    ) VALUES (
      _winner_id, _s.seller_id, _label, _s.item_description,
      _winning_bid + _ship_for_this, _ship_for_this, _s.item_image_url, _stream_id,
      _s.current_condition, 'pending', 'awaiting_payment',
      COALESCE(_p.full_name, _winner_username), COALESCE(_p.address_line1, ''),
      COALESCE(_p.address_city, ''), COALESCE(_p.address_state, ''),
      COALESCE(_p.address_zip, ''), COALESCE(_p.address_country, 'US')
    ) RETURNING id INTO _order_id;
  EXCEPTION WHEN unique_violation THEN
    SELECT id INTO _order_id FROM public.orders
      WHERE stream_id = _stream_id AND buyer_id = _winner_id
      ORDER BY created_at DESC LIMIT 1;
  END;

  UPDATE public.live_streams SET
    winner_id = _winner_id,
    winning_bid = _winning_bid,
    winner_username = _winner_username,
    round_number = _next_round
  WHERE id = _stream_id;

  INSERT INTO public.notifications (user_id, sender_id, type, body, link)
    VALUES (_winner_id, _winner_id, 'won',
      '🎉 You won Bid #' || _next_round || ' "' || _item_name ||
      '" for $' || _winning_bid || '. Tap to pay now.', '/orders');

  INSERT INTO public.notifications (user_id, sender_id, type, body, link)
    VALUES (_s.seller_id, _s.seller_id, 'sale',
      '💰 Sold "' || _item_name || '" to @' || COALESCE(_winner_username,'buyer') ||
      ' for $' || _winning_bid, '/store');

  PERFORM set_config('app.bypass_dm_check', 'on', true);
  BEGIN
    INSERT INTO public.direct_messages (sender_id, sender_username, recipient_id, content)
    VALUES (_s.seller_id, COALESCE(_seller_username, 'seller'), _winner_id,
      '🏆 You won "' || _item_name || '" for $' || _winning_bid ||
      CASE WHEN _ship_for_this > 0 THEN ' + $' || _ship_for_this || ' shipping' ELSE '' END || '. Complete payment from your Orders/Cart.');
  EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'winner DM failed: %', SQLERRM;
  END;

  INSERT INTO public.stream_payment_events
    (stream_id, seller_id, buyer_id, buyer_username, order_id, event_type, amount, item_label, message)
  VALUES
    (_stream_id, _s.seller_id, _winner_id, _winner_username, _order_id, 'payment_pending', _winning_bid, _label,
     'Awaiting payment for auction win');

  INSERT INTO public.audit_logs (actor_id, action, target_type, target_id, meta)
    VALUES (_caller, 'auction_finalized', 'live_stream', _stream_id,
            jsonb_build_object('winner_id', _winner_id, 'amount', _winning_bid, 'shipping_amount', _ship_for_this, 'order_id', _order_id, 'round', _next_round));

  RETURN jsonb_build_object('ok', true, 'order_id', _order_id, 'winner_id', _winner_id, 'winner_username', _winner_username, 'amount', _winning_bid, 'shipping_amount', _ship_for_this, 'round_number', _next_round);
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_public_id()
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v text;
BEGIN
  LOOP
    v := upper(substr(md5(gen_random_uuid()::text), 1, 8));
    EXIT WHEN NOT EXISTS (SELECT 1 FROM public.profiles WHERE public_id = v);
  END LOOP;
  RETURN v;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_buyer_private_insights(_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _caller uuid := auth.uid(); _r record;
BEGIN
  IF _caller IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT (_caller=_user_id OR public.has_role(_caller,'admin') OR public.has_role(_caller,'owner') OR public.has_role(_caller,'moderator')
     OR EXISTS (SELECT 1 FROM public.orders WHERE seller_id=_caller AND buyer_id=_user_id)) THEN
    RAISE EXCEPTION 'Insufficient permissions';
  END IF;
  SELECT * INTO _r FROM public.get_buyer_reputation(_user_id);
  RETURN to_jsonb(_r);
END $function$

CREATE OR REPLACE FUNCTION public.get_buyer_public_badges(_user_id uuid)
 RETURNS TABLE(badge text, label text, tier text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _r record;
BEGIN
  SELECT * INTO _r FROM public.get_buyer_reputation(_user_id);
  IF _r.completed_purchases >= 35 AND _r.payment_success_rate >= 95 THEN badge:='trusted_buyer'; label:='Trusted Buyer'; tier:='gold'; RETURN NEXT; END IF;
  IF _r.avg_payment_minutes IS NOT NULL AND _r.avg_payment_minutes <= 30 AND _r.paid_orders >= 5 THEN badge:='fast_payer'; label:='Fast Payer'; tier:='platinum'; RETURN NEXT; END IF;
  IF EXISTS (SELECT 1 FROM public.profiles WHERE id=_user_id AND (buyer_verified=true OR phone_verified=true)) THEN badge:='verified_buyer'; label:='Verified Buyer'; tier:='silver'; RETURN NEXT; END IF;
  IF _r.completed_purchases >= 10 THEN badge:='repeat_customer'; label:='Repeat Customer'; tier:='silver'; RETURN NEXT; END IF;
  IF (SELECT COUNT(*) FROM public.live_bids WHERE bidder_id=_user_id) >= 100 THEN badge:='auction_veteran'; label:='Auction Veteran'; tier:='gold'; RETURN NEXT; END IF;
  BEGIN
    IF (SELECT COUNT(*) FROM public.tips WHERE from_user_id=_user_id) >= 5 THEN badge:='supportive_buyer'; label:='Supportive Buyer'; tier:='silver'; RETURN NEXT; END IF;
  EXCEPTION WHEN OTHERS THEN NULL; END;
  RETURN;
END $function$

CREATE OR REPLACE FUNCTION public.get_seller_badges(_seller_id uuid)
 RETURNS TABLE(badge text, label text, tier text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _s record; _verified boolean; _live_verified boolean;
BEGIN
  SELECT * INTO _s FROM public.get_seller_stats(_seller_id);
  SELECT (verification_status = 'verified'), live_verified
    INTO _verified, _live_verified
  FROM public.profiles WHERE id = _seller_id;

  IF COALESCE(_verified, false) OR COALESCE(_live_verified, false) THEN
    badge := 'verified'; label := 'Verified Seller'; tier := 'gold'; RETURN NEXT;
  END IF;

  IF _s.completed_sales >= 25 AND _s.avg_rating >= 4.5 AND _s.success_rate >= 95
     AND _s.late_rate <= 5 AND _s.refund_rate <= 3 THEN
    badge := 'trusted'; label := 'Trusted Seller'; tier := 'gold'; RETURN NEXT;
  END IF;

  IF _s.completed_sales >= 10 AND _s.avg_shipping_days IS NOT NULL AND _s.avg_shipping_days <= 1 THEN
    badge := 'same_day'; label := 'Same-Day Shipper'; tier := 'platinum'; RETURN NEXT;
  ELSIF _s.completed_sales >= 5 AND _s.avg_shipping_days IS NOT NULL AND _s.avg_shipping_days <= 2 THEN
    badge := 'fast'; label := 'Fast Shipper'; tier := 'silver'; RETURN NEXT;
  END IF;

  IF _s.review_count >= 10 AND _s.avg_rating >= 4.7 THEN
    badge := 'top_rated'; label := 'Top Rated'; tier := 'gold'; RETURN NEXT;
  END IF;

  RETURN;
END $function$

CREATE OR REPLACE FUNCTION public.get_seller_response_badges(_seller_id uuid)
 RETURNS TABLE(badge text, label text, tier text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _s record; _recent int;
BEGIN
  SELECT * INTO _s FROM public.get_seller_stats(_seller_id);
  IF _s.avg_response_minutes IS NOT NULL AND _s.avg_response_minutes <= 60 THEN badge:='responds_fast'; label:='Responds Fast'; tier:='gold'; RETURN NEXT; END IF;
  SELECT COUNT(*) INTO _recent FROM public.live_streams WHERE seller_id=_seller_id AND COALESCE(started_at, created_at) > now() - interval '14 days';
  IF _recent >= 3 THEN badge:='active_seller'; label:='Active Seller'; tier:='silver'; RETURN NEXT; END IF;
  IF _s.review_count >= 10 AND _s.avg_rating >= 4.7 THEN badge:='top_rated'; label:='Top Rated'; tier:='platinum'; RETURN NEXT; END IF;
  RETURN;
END $function$

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _owner uuid;
BEGIN
  INSERT INTO public.profiles (id, username, is_seller)
  VALUES (
    NEW.id,
    COALESCE(NEW.raw_user_meta_data->>'username', split_part(NEW.email, '@', 1)),
    COALESCE((NEW.raw_user_meta_data->>'is_seller')::boolean, false)
  );
  SELECT user_id INTO _owner FROM public.user_roles WHERE role = 'owner' LIMIT 1;
  IF _owner IS NOT NULL AND _owner <> NEW.id THEN
    INSERT INTO public.follows (follower_id, followee_id) VALUES (NEW.id, _owner)
    ON CONFLICT DO NOTHING;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.is_in_quiet_hours(_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  tz text;
  qs smallint;
  qe smallint;
  hr smallint;
BEGIN
  SELECT COALESCE(timezone, 'UTC'), notify_quiet_start, notify_quiet_end
    INTO tz, qs, qe
    FROM profiles WHERE id = _user_id;
  IF qs IS NULL OR qe IS NULL THEN RETURN false; END IF;
  hr := EXTRACT(HOUR FROM (now() AT TIME ZONE tz))::smallint;
  IF qs = qe THEN RETURN false; END IF;
  IF qs < qe THEN
    RETURN hr >= qs AND hr < qe;
  ELSE
    -- Window wraps midnight (e.g. 22 -> 7)
    RETURN hr >= qs OR hr < qe;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.listings_block_inline_images()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.image_url IS NOT NULL AND NEW.image_url LIKE 'data:%' THEN
    RAISE EXCEPTION 'Listing image_url must be a hosted URL, not inline base64 data. Upload via storage.';
  END IF;
  IF NEW.back_image_url IS NOT NULL AND NEW.back_image_url LIKE 'data:%' THEN
    RAISE EXCEPTION 'Listing back_image_url must be a hosted URL, not inline base64 data. Upload via storage.';
  END IF;
  -- Reasonable URL length sanity check
  IF NEW.image_url IS NOT NULL AND length(NEW.image_url) > 2000 THEN
    RAISE EXCEPTION 'image_url too long';
  END IF;
  IF NEW.back_image_url IS NOT NULL AND length(NEW.back_image_url) > 2000 THEN
    RAISE EXCEPTION 'back_image_url too long';
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.live_streams_restrict_bidder_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  -- Never let a non-owner persist Cloudflare ingest secrets.
  IF v_uid IS DISTINCT FROM OLD.seller_id THEN
    NEW.cf_live_input_id := OLD.cf_live_input_id;
    NEW.cf_rtmps_url    := OLD.cf_rtmps_url;
    NEW.cf_stream_key   := OLD.cf_stream_key;
  END IF;

  IF v_uid = OLD.seller_id THEN
    RETURN NEW;
  END IF;

  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  -- Bidders may ONLY change current_bid + current_bidder_id.
  -- Force every other column back to its previous value.
  NEW.id                          := OLD.id;
  NEW.seller_id                   := OLD.seller_id;
  NEW.title                       := OLD.title;
  NEW.description                 := OLD.description;
  NEW.status                      := OLD.status;
  NEW.is_active                   := OLD.is_active;
  NEW.created_at                  := OLD.created_at;
  NEW.started_at                  := OLD.started_at;
  NEW.ended_at                    := OLD.ended_at;
  NEW.winner_id                   := OLD.winner_id;
  NEW.winner_username             := OLD.winner_username;
  NEW.winning_bid                 := OLD.winning_bid;
  NEW.starting_bid                := OLD.starting_bid;
  NEW.shipping_price              := OLD.shipping_price;
  NEW.shipping_method             := OLD.shipping_method;
  NEW.item_image_url              := OLD.item_image_url;
  NEW.thumbnail_url               := OLD.thumbnail_url;
  NEW.cf_playback_hls             := OLD.cf_playback_hls;
  NEW.cf_video_uid                := OLD.cf_video_uid;
  NEW.cf_whip_url                 := OLD.cf_whip_url;
  NEW.cf_live_input_id            := OLD.cf_live_input_id;
  NEW.cf_rtmps_url                := OLD.cf_rtmps_url;
  NEW.cf_stream_key               := OLD.cf_stream_key;
  NEW.break_mode                  := OLD.break_mode;
  NEW.quick_start_enabled         := OLD.quick_start_enabled;
  NEW.default_timer_sec           := OLD.default_timer_sec;
  NEW.default_starting_bid        := OLD.default_starting_bid;
  NEW.chat_slow_mode_sec          := OLD.chat_slow_mode_sec;
  NEW.sudden_death_enabled        := OLD.sudden_death_enabled;
  NEW.sudden_death_max_triggers   := OLD.sudden_death_max_triggers;
  NEW.sudden_death_seconds_added  := OLD.sudden_death_seconds_added;
  NEW.quantity                    := OLD.quantity;
  NEW.auction_reveal_mode         := OLD.auction_reveal_mode;

  -- Validate the only allowed change.
  IF NEW.current_bid IS DISTINCT FROM OLD.current_bid THEN
    IF OLD.current_bid IS NOT NULL AND NEW.current_bid <= OLD.current_bid THEN
      RAISE EXCEPTION 'New bid must exceed current bid';
    END IF;
    IF NEW.current_bidder_id IS DISTINCT FROM v_uid THEN
      RAISE EXCEPTION 'Bidder must be the authenticated user';
    END IF;
  ELSIF NEW.current_bidder_id IS DISTINCT FROM OLD.current_bidder_id THEN
    -- No bid change but bidder field changed -> reject
    RAISE EXCEPTION 'Cannot change current_bidder_id without raising the bid';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.lock_order_funds(_order_id uuid, _reason text, _notes text DEFAULT NULL::text)
 RETURNS payout_locks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _o public.orders; _amt BIGINT; _row public.payout_locks;
BEGIN
  SELECT * INTO _o FROM public.orders WHERE id = _order_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'order not found'; END IF;
  _amt := COALESCE(
    (_o.seller_payout_amount * 100)::bigint,
    (_o.amount * (1 - COALESCE(_o.commission_rate,0.05)) * 100)::bigint
  );
  -- Avoid duplicate active lock per (order, reason)
  SELECT * INTO _row FROM public.payout_locks
   WHERE order_id = _order_id AND reason = _reason AND released_at IS NULL LIMIT 1;
  IF FOUND THEN RETURN _row; END IF;

  INSERT INTO public.payout_locks (order_id, user_id, amount_cents, reason, notes)
  VALUES (_order_id, _o.seller_id, _amt, _reason, _notes)
  RETURNING * INTO _row;
  RETURN _row;
END $function$

CREATE OR REPLACE FUNCTION public.log_account_event(_subject_user_id uuid, _event_type audit_event_type, _summary text, _severity audit_severity DEFAULT 'info'::audit_severity, _details jsonb DEFAULT '{}'::jsonb, _actor_user_id uuid DEFAULT NULL::uuid, _order_id uuid DEFAULT NULL::uuid, _stream_id uuid DEFAULT NULL::uuid, _payment_intent_id text DEFAULT NULL::text, _dispute_id uuid DEFAULT NULL::uuid, _payout_id uuid DEFAULT NULL::uuid, _report_id uuid DEFAULT NULL::uuid, _evidence_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  new_id uuid;
  actor_role_val text;
BEGIN
  IF _actor_user_id IS NOT NULL THEN
    SELECT role::text INTO actor_role_val FROM public.user_roles
      WHERE user_id = _actor_user_id ORDER BY role LIMIT 1;
  END IF;
  INSERT INTO public.account_audit_log(
    subject_user_id, actor_user_id, actor_role, event_type, severity, summary, details,
    order_id, stream_id, payment_intent_id, dispute_id, payout_id, report_id, evidence_id
  ) VALUES (
    _subject_user_id, _actor_user_id, actor_role_val, _event_type, _severity, _summary, _details,
    _order_id, _stream_id, _payment_intent_id, _dispute_id, _payout_id, _report_id, _evidence_id
  ) RETURNING id INTO new_id;
  RETURN new_id;
END $function$

CREATE OR REPLACE FUNCTION public.log_admin_action(_action text, _target_table text DEFAULT NULL::text, _target_id uuid DEFAULT NULL::uuid, _subject_user_id uuid DEFAULT NULL::uuid, _before jsonb DEFAULT NULL::jsonb, _after jsonb DEFAULT NULL::jsonb, _reason text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  new_id uuid;
  caller uuid := auth.uid();
BEGIN
  IF caller IS NULL OR NOT (
    has_role(caller,'admin') OR has_role(caller,'owner') OR has_role(caller,'moderator')
  ) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  INSERT INTO public.admin_action_log(
    admin_id, action, target_table, target_id, subject_user_id, before_state, after_state, reason
  ) VALUES (caller, _action, _target_table, _target_id, _subject_user_id, _before, _after, _reason)
  RETURNING id INTO new_id;
  RETURN new_id;
END $function$

CREATE OR REPLACE FUNCTION public.log_audit_event(_action text, _target_type text DEFAULT NULL::text, _target_id uuid DEFAULT NULL::uuid, _meta jsonb DEFAULT '{}'::jsonb, _ip_hash text DEFAULT NULL::text, _user_agent text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _username text;
  _id uuid;
BEGIN
  IF _action IS NULL OR length(btrim(_action)) = 0 OR length(_action) > 64 THEN
    RAISE EXCEPTION 'Invalid action';
  END IF;
  IF _uid IS NOT NULL THEN
    SELECT username INTO _username FROM public.profiles WHERE id = _uid;
  END IF;
  INSERT INTO public.audit_logs (actor_id, actor_username, action, target_type, target_id, meta, ip_hash, user_agent)
  VALUES (_uid, _username, _action, _target_type, _target_id, COALESCE(_meta, '{}'::jsonb), _ip_hash, LEFT(_user_agent, 300))
  RETURNING id INTO _id;
  RETURN _id;
END;
$function$

CREATE OR REPLACE FUNCTION public.mark_order_packed(_order_id uuid)
 RETURNS TABLE(prev_status text, new_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_seller uuid; v_prev text;
BEGIN
  SELECT seller_id, prep_status INTO v_seller, v_prev FROM public.orders WHERE id = _order_id;
  IF v_seller IS NULL THEN RAISE EXCEPTION 'Order not found'; END IF;
  IF v_seller <> auth.uid() THEN RAISE EXCEPTION 'Not authorized'; END IF;
  UPDATE public.orders
    SET prep_status = 'packed', packed_at = COALESCE(packed_at, now())
    WHERE id = _order_id AND prep_status NOT IN ('shipped','delivered');
  prev_status := v_prev; new_status := 'packed';
  RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION public.mark_order_ready(_order_id uuid)
 RETURNS TABLE(prev_status text, new_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_seller uuid; v_prev text;
BEGIN
  SELECT seller_id, prep_status INTO v_seller, v_prev FROM public.orders WHERE id = _order_id;
  IF v_seller IS NULL THEN RAISE EXCEPTION 'Order not found'; END IF;
  IF v_seller <> auth.uid() THEN RAISE EXCEPTION 'Not authorized'; END IF;
  UPDATE public.orders
    SET prep_status = 'ready_for_dropoff',
        ready_at = COALESCE(ready_at, now()),
        packed_at = COALESCE(packed_at, now())
    WHERE id = _order_id AND prep_status NOT IN ('shipped','delivered');
  prev_status := v_prev; new_status := 'ready_for_dropoff';
  RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION public.move_to_dlq(source_queue text, dlq_name text, message_id bigint, payload jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE new_id BIGINT;
BEGIN
  SELECT pgmq.send(dlq_name, payload) INTO new_id;
  PERFORM pgmq.delete(source_queue, message_id);
  RETURN new_id;
EXCEPTION WHEN undefined_table THEN
  BEGIN
    PERFORM pgmq.create(dlq_name);
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
  SELECT pgmq.send(dlq_name, payload) INTO new_id;
  BEGIN
    PERFORM pgmq.delete(source_queue, message_id);
  EXCEPTION WHEN undefined_table THEN
    NULL;
  END;
  RETURN new_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.notifications_validate_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  recent_count int;
  allowed_types text[] := ARRAY[
    'won','sale','order','payment','payment_failed','payment_pending',
    'follow','new_follower','like','comment','mention','reply','dm','message',
    'collab_invite','collab_join','collab_request','collab_accepted',
    'giveaway','giveaway_win','tip','shoutout','ko_request','ko_accepted',
    'verification','verification_request','seller_agreement_reaccept','dispute','dispute_update',
    'dispute_opened','dispute_evidence_submitted','dispute_status_changed','dispute_escalated','dispute_resolved',
    'report_filed','report_resolved','admin_warning_issued','admin_note',
    'shipping','shipped','delivered','listing','listing_sold','offer',
    'system','announcement','warning','support',
    'seller_live','order_packed','order_ready_for_dropoff','order_shipped','order_delivered','order_cancelled'
  ];
BEGIN
  NEW.sender_id := auth.uid();
  IF NEW.body IS NULL OR length(NEW.body) = 0 OR length(NEW.body) > 500 THEN
    RAISE EXCEPTION 'Notification body must be 1..500 chars';
  END IF;
  IF NEW.type IS NULL OR length(NEW.type) > 32 THEN
    RAISE EXCEPTION 'Invalid notification type';
  END IF;
  IF NOT (NEW.type = ANY(allowed_types)) THEN
    RAISE EXCEPTION 'Notification type % is not allowed', NEW.type;
  END IF;
  IF NEW.link IS NOT NULL THEN
    IF length(NEW.link) > 200 THEN
      RAISE EXCEPTION 'Notification link too long';
    END IF;
    IF left(NEW.link, 1) <> '/' THEN
      RAISE EXCEPTION 'Notification link must be an internal path starting with /';
    END IF;
  END IF;
  IF NEW.user_id = auth.uid() THEN
    RETURN NEW;
  END IF;
  SELECT COUNT(*) INTO recent_count
  FROM public.notifications
  WHERE sender_id = auth.uid()
    AND user_id <> auth.uid()
    AND created_at > now() - interval '1 hour';
  IF recent_count >= 60 THEN
    RAISE EXCEPTION 'Notification rate limit exceeded';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.notify_new_follower()
 RETURNS trigger
 LANGUAGE plpgsql
