CREATE OR REPLACE FUNCTION public.notify_user(_user_id uuid, _type text, _category text, _body text, _link text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _allowed boolean; _id uuid;
BEGIN
  IF _user_id IS NULL THEN RETURN NULL; END IF;
  SELECT TRUE INTO _allowed FROM public.get_notify_targets(ARRAY[_user_id], _category) LIMIT 1;
  IF NOT COALESCE(_allowed, false) THEN RETURN NULL; END IF;
  INSERT INTO public.notifications (user_id, type, body, link)
  VALUES (_user_id, _type, _body, _link)
  RETURNING id INTO _id;
  RETURN _id;
END $function$

CREATE OR REPLACE FUNCTION public.open_daily_crate()
 RETURNS TABLE(reward_slug text, reward_name text, kind text, rarity text, value text, icon text, xp_bonus integer, already_opened boolean, is_new boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid UUID := auth.uid();
  last_date DATE;
  total_w BIGINT;
  pick BIGINT;
  chosen RECORD;
  newly BOOLEAN := false;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;

  SELECT last_opened_date INTO last_date FROM public.user_crate_state WHERE user_id = uid;

  IF last_date = CURRENT_DATE THEN
    RETURN QUERY SELECT NULL::text, NULL::text, NULL::text, NULL::text, NULL::text, NULL::text, 0, true, false;
    RETURN;
  END IF;

  SELECT COALESCE(SUM(weight), 0) INTO total_w FROM public.crate_rewards WHERE is_active;
  IF total_w = 0 THEN RAISE EXCEPTION 'No rewards configured'; END IF;

  pick := floor(random() * total_w)::bigint;
  FOR chosen IN
    SELECT * FROM public.crate_rewards WHERE is_active ORDER BY created_at
  LOOP
    IF pick < chosen.weight THEN EXIT; END IF;
    pick := pick - chosen.weight;
  END LOOP;

  -- record crate open
  INSERT INTO public.user_crate_state (user_id, last_opened_date, total_opened)
  VALUES (uid, CURRENT_DATE, 1)
  ON CONFLICT (user_id) DO UPDATE
    SET last_opened_date = CURRENT_DATE,
        total_opened = public.user_crate_state.total_opened + 1,
        updated_at = now();

  -- grant the cosmetic (track new vs duplicate)
  IF chosen.kind <> 'xp' THEN
    INSERT INTO public.user_rewards (user_id, reward_slug, quantity)
    VALUES (uid, chosen.slug, 1)
    ON CONFLICT (user_id, reward_slug) DO UPDATE
      SET quantity = public.user_rewards.quantity + 1;
    GET DIAGNOSTICS newly = ROW_COUNT;
    -- determine if this was the first time owning it
    SELECT (quantity = 1) INTO newly FROM public.user_rewards
      WHERE user_id = uid AND reward_slug = chosen.slug;
  END IF;

  -- award bonus XP (always at least a small base for opening)
  PERFORM public.award_xp(GREATEST(10, chosen.xp_bonus), 'crate:' || chosen.slug, CURRENT_DATE::text);

  RETURN QUERY SELECT chosen.slug, chosen.name, chosen.kind, chosen.rarity,
                      chosen.value, chosen.icon, GREATEST(10, chosen.xp_bonus), false, newly;
END;
$function$

CREATE OR REPLACE FUNCTION public.orders_protect_payouts()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Lock if delivery still unconfirmed past shipping_due_at
  IF NEW.payment_status = 'paid' AND NEW.status = 'pending' AND NEW.shipping_due_at IS NOT NULL
     AND NEW.shipping_due_at < now() THEN
    PERFORM public.lock_order_funds(NEW.id, 'delivery_unconfirmed', 'past shipping due');
  END IF;

  -- Refund => lock until reconciled, recalc trust
  IF (TG_OP = 'UPDATE') AND COALESCE(OLD.refunded_amount,0) = 0 AND COALESCE(NEW.refunded_amount,0) > 0 THEN
    PERFORM public.lock_order_funds(NEW.id, 'refund_pending', 'refund issued');
    PERFORM public.recalc_seller_trust(NEW.seller_id);
  END IF;

  -- Delivered => release any delivery_unconfirmed locks + recalc
  IF (TG_OP = 'UPDATE') AND OLD.status IS DISTINCT FROM NEW.status AND NEW.status = 'delivered' THEN
    PERFORM public.release_order_funds(NEW.id, 'delivery_unconfirmed');
    PERFORM public.recalc_seller_trust(NEW.seller_id);
  END IF;

  -- Cancelled => release locks + recalc
  IF (TG_OP = 'UPDATE') AND OLD.status IS DISTINCT FROM NEW.status AND NEW.status = 'cancelled' THEN
    PERFORM public.release_order_funds(NEW.id);
    PERFORM public.recalc_seller_trust(NEW.seller_id);
  END IF;

  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.perf_metrics_validate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _recent int;
BEGIN
  IF length(NEW.route) > 200 THEN NEW.route := left(NEW.route,200); END IF;
  IF length(NEW.method) > 10 THEN NEW.method := left(NEW.method,10); END IF;
  IF length(NEW.kind) > 32 THEN NEW.kind := left(NEW.kind,32); END IF;
  IF NEW.duration_ms < 0 THEN NEW.duration_ms := 0; END IF;
  IF NEW.duration_ms > 600000 THEN NEW.duration_ms := 600000; END IF;
  IF auth.uid() IS NOT NULL THEN
    SELECT count(*) INTO _recent FROM public.perf_metrics
      WHERE user_id = auth.uid() AND created_at > now() - interval '1 minute';
    IF _recent >= 600 THEN RAISE EXCEPTION 'perf_metrics rate limit'; END IF;
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.place_listing_bid(_listing_id uuid, _amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _username text; _l listings%ROWTYPE; _unpaid int;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF _amount IS NULL OR _amount <= 0 THEN RAISE EXCEPTION 'Invalid bid amount'; END IF;
  IF public.is_bid_restricted(_uid) THEN RAISE EXCEPTION 'Account is currently restricted from bidding. Contact support.'; END IF;
  SELECT COUNT(*) INTO _unpaid FROM public.orders WHERE buyer_id=_uid AND payment_status='awaiting_payment';
  IF _unpaid > 0 THEN RAISE EXCEPTION 'Pay your pending order before bidding'; END IF;
  SELECT * INTO _l FROM public.listings WHERE id=_listing_id FOR UPDATE;
  IF _l.id IS NULL THEN RAISE EXCEPTION 'Listing not found'; END IF;
  IF _l.seller_id=_uid THEN RAISE EXCEPTION 'Sellers cannot bid on their own listing'; END IF;
  IF COALESCE(_l.listing_type, 'buy_now') <> 'auction' AND NOT _l.is_auction THEN RAISE EXCEPTION 'Listing is not an auction'; END IF;
  IF _l.auction_status <> 'active' THEN RAISE EXCEPTION 'Auction is not active'; END IF;
  IF _l.auction_ends_at IS NOT NULL AND _l.auction_ends_at <= now() THEN RAISE EXCEPTION 'Auction ended'; END IF;
  IF _amount <= COALESCE(_l.current_bid, _l.starting_bid, 0) THEN RAISE EXCEPTION 'Bid must be higher than current bid'; END IF;
  SELECT username INTO _username FROM public.profiles WHERE id=_uid;
  INSERT INTO public.listing_bids (listing_id, user_id, username, amount) VALUES (_listing_id, _uid, _username, _amount);
  UPDATE public.listings SET current_bid=_amount, top_bidder_id=_uid WHERE id=_listing_id;
  IF _l.auction_ends_at IS NOT NULL AND _l.auction_ends_at - now() < interval '30 seconds' THEN
    UPDATE public.listings SET auction_ends_at = now() + interval '60 seconds' WHERE id=_listing_id;
  END IF;
  RETURN jsonb_build_object('ok', true, 'amount', _amount);
END; $function$

CREATE OR REPLACE FUNCTION public.place_live_bid(_stream_id uuid, _amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _username text;
  _s public.live_streams%ROWTYPE;
  _unpaid int;
  _min_inc numeric;
  _cur numeric;
  _remaining_ms bigint;
  _extended boolean := false;
  _sd_win boolean := false;
  _new_ends timestamptz;
  _exts int;
  _sd_sec int;
  _sd_max int;
  _dup_id uuid;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF _amount IS NULL OR _amount <= 0 THEN RAISE EXCEPTION 'Invalid bid amount'; END IF;
  IF public.is_bid_restricted(_uid) THEN RAISE EXCEPTION 'Account is currently restricted from bidding. Contact support.'; END IF;

  SELECT id INTO _dup_id
  FROM public.live_bids
  WHERE stream_id = _stream_id
    AND bidder_id = _uid
    AND amount = _amount
    AND created_at > now() - interval '2 seconds'
  ORDER BY created_at DESC
  LIMIT 1;
  IF _dup_id IS NOT NULL THEN
    RETURN jsonb_build_object('ok', true, 'amount', _amount, 'duplicate', true);
  END IF;

  SELECT COUNT(*) INTO _unpaid FROM public.orders WHERE buyer_id = _uid AND payment_status = 'awaiting_payment';
  IF _unpaid > 0 THEN RAISE EXCEPTION 'Pay your pending order before bidding'; END IF;

  SELECT * INTO _s FROM public.live_streams WHERE id = _stream_id FOR UPDATE;
  IF _s.id IS NULL THEN RAISE EXCEPTION 'Stream not found'; END IF;
  IF _s.seller_id = _uid THEN RAISE EXCEPTION 'Sellers cannot bid on their own stream'; END IF;
  IF _s.status <> 'live' THEN RAISE EXCEPTION 'Stream is not live'; END IF;
  IF _s.ends_at IS NULL OR _s.ends_at <= now() THEN RAISE EXCEPTION 'Auction not running'; END IF;
  IF public.is_bid_blocked(_stream_id, _uid) THEN RAISE EXCEPTION 'You are blocked from bidding here'; END IF;

  _cur := COALESCE(_s.current_bid, 0);
  _min_inc := GREATEST(COALESCE(_s.min_bid_increment, 1), 0.01);
  IF _amount < _cur + _min_inc THEN RAISE EXCEPTION 'Bid must be at least $%', (_cur + _min_inc)::text; END IF;

  SELECT username INTO _username FROM public.profiles WHERE id = _uid;
  _remaining_ms := EXTRACT(EPOCH FROM (_s.ends_at - now())) * 1000;
  _exts := COALESCE(_s.snipe_extends, 0);
  _sd_sec := GREATEST(1, COALESCE(_s.sudden_death_seconds_added, 5));
  _sd_max := GREATEST(1, COALESCE(_s.sudden_death_max_triggers, 3));

  IF COALESCE(_s.sudden_death_active, false) THEN
    _new_ends := now() + interval '1200 milliseconds';
    _sd_win := true;
    UPDATE public.live_streams
      SET current_bid = _amount, current_bidder_id = _uid, ends_at = _new_ends, sudden_death_active = false
      WHERE id = _stream_id;
  ELSIF COALESCE(_s.sudden_death_enabled, false) AND _remaining_ms > 0 AND _remaining_ms <= 3000 THEN
    _new_ends := GREATEST(_s.ends_at, now()) + make_interval(secs => _sd_sec);
    _extended := true;
    UPDATE public.live_streams
      SET current_bid = _amount,
          current_bidder_id = _uid,
          ends_at = _new_ends,
          snipe_extends = _exts + 1,
          sudden_death_active = ((_exts + 1) >= _sd_max)
      WHERE id = _stream_id;
  ELSE
    UPDATE public.live_streams
      SET current_bid = _amount, current_bidder_id = _uid
      WHERE id = _stream_id;
  END IF;

  BEGIN
    INSERT INTO public.live_bids (stream_id, bidder_id, bidder_username, amount, round_number, was_anti_snipe, was_sudden_death)
    VALUES (_stream_id, _uid, _username, _amount, _s.round_number, _extended, _sd_win);
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object('ok', true, 'amount', _amount, 'duplicate', true);
  END;

  INSERT INTO public.audit_logs (actor_id, actor_username, action, target_type, target_id, meta)
  VALUES (_uid, _username, 'live_bid_placed', 'live_stream', _stream_id,
          jsonb_build_object('amount', _amount, 'prev_bid', _cur, 'extended', _extended, 'sudden_death_win', _sd_win));

  RETURN jsonb_build_object('ok', true, 'amount', _amount, 'extended', _extended, 'sudden_death_win', _sd_win);
END;
$function$

CREATE OR REPLACE FUNCTION public.prevent_owner_suspension()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = NEW.user_id AND role = 'owner') THEN
    RAISE EXCEPTION 'The owner cannot be suspended or banned';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.prevent_profile_privilege_escalation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  is_privileged boolean;
  cu text := current_user;
BEGIN
  -- Bypass when running via service role, postgres, or any SECURITY DEFINER
  -- function owned by an elevated role.
  IF cu IN ('postgres', 'supabase_admin', 'service_role', 'authenticator') THEN
    RETURN NEW;
  END IF;

  -- No JWT (server context) — let it through.
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;

  is_privileged := public.has_role(auth.uid(), 'admin'::app_role)
                OR public.has_role(auth.uid(), 'owner'::app_role);

  IF is_privileged THEN
    RETURN NEW;
  END IF;

  NEW.is_seller := OLD.is_seller;
  NEW.buyer_verified := OLD.buyer_verified;
  NEW.id_status := OLD.id_status;
  NEW.id_document_url := OLD.id_document_url;
  NEW.seller_status := OLD.seller_status;
  NEW.phone_verified := OLD.phone_verified;
  NEW.phone_verified_at := OLD.phone_verified_at;
  NEW.stripe_account_id := OLD.stripe_account_id;
  NEW.stripe_payouts_enabled := OLD.stripe_payouts_enabled;
  NEW.stripe_charges_enabled := OLD.stripe_charges_enabled;
  NEW.stripe_onboarding_status := OLD.stripe_onboarding_status;
  NEW.live_verified := OLD.live_verified;
  NEW.age_verified := OLD.age_verified;
  NEW.age_verified_at := OLD.age_verified_at;
  NEW.tos_accepted := OLD.tos_accepted;
  NEW.tos_accepted_at := OLD.tos_accepted_at;
  NEW.guidelines_accepted := OLD.guidelines_accepted;
  NEW.guidelines_accepted_at := OLD.guidelines_accepted_at;
  NEW.agreements_version := OLD.agreements_version;
  NEW.agreements_completed_at := OLD.agreements_completed_at;
  NEW.agreements_review_required := OLD.agreements_review_required;
  NEW.creator_tier := OLD.creator_tier;
  NEW.verification_status := OLD.verification_status;
  NEW.verified_at := OLD.verified_at;
  NEW.verification_reason := OLD.verification_reason;
  NEW.verification_requested_at := OLD.verification_requested_at;
  NEW.verification_history := OLD.verification_history;
  NEW.public_id := OLD.public_id;
  NEW.id := OLD.id;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.protect_owner_role()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND OLD.role = 'owner' THEN
    RAISE EXCEPTION 'Owner role cannot be removed';
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.role = 'owner' AND NEW.role <> 'owner' THEN
    RAISE EXCEPTION 'Owner role cannot be changed';
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.purge_old_perf_data()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _n INT;
BEGIN
  DELETE FROM public.perf_metrics WHERE created_at < now() - interval '7 days';
  GET DIAGNOSTICS _n = ROW_COUNT;
  DELETE FROM public.error_logs WHERE created_at < now() - interval '30 days';
  DELETE FROM public.perf_alert_events WHERE created_at < now() - interval '30 days';
  RETURN _n;
END; $function$

CREATE OR REPLACE FUNCTION public.rate_limit_card_scan(_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _hour int;
  _day int;
  _hour_limit int := 30;
  _day_limit int := 200;
BEGIN
  IF _user_id IS NULL THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'unauthenticated');
  END IF;

  -- Admins/owners exempt
  IF public.has_role(_user_id, 'admin') OR public.has_role(_user_id, 'owner') THEN
    RETURN jsonb_build_object('allowed', true, 'reason', 'admin');
  END IF;

  SELECT COUNT(*) INTO _hour FROM public.card_scans
   WHERE user_id = _user_id AND status = 'ok' AND created_at > now() - interval '1 hour';
  IF _hour >= _hour_limit THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'hour_limit', 'limit', _hour_limit, 'used', _hour);
  END IF;

  SELECT COUNT(*) INTO _day FROM public.card_scans
   WHERE user_id = _user_id AND status = 'ok' AND created_at > now() - interval '24 hours';
  IF _day >= _day_limit THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'day_limit', 'limit', _day_limit, 'used', _day);
  END IF;

  RETURN jsonb_build_object(
    'allowed', true,
    'hour_used', _hour, 'hour_limit', _hour_limit,
    'day_used', _day, 'day_limit', _day_limit
  );
END; $function$

CREATE OR REPLACE FUNCTION public.read_email_batch(queue_name text, batch_size integer, vt integer)
 RETURNS TABLE(msg_id bigint, read_ct integer, message jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY SELECT r.msg_id, r.read_ct, r.message FROM pgmq.read(queue_name, vt, batch_size) r;
EXCEPTION WHEN undefined_table THEN
  PERFORM pgmq.create(queue_name);
  RETURN;
END;
$function$

CREATE OR REPLACE FUNCTION public.rearm_next_round(_stream_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _s public.live_streams%ROWTYPE;
  _caller uuid := auth.uid();
  _is_admin boolean;
  _remaining int;
  _sec int;
  _start numeric;
BEGIN
  SELECT * INTO _s FROM public.live_streams WHERE id = _stream_id FOR UPDATE;
  IF _s.id IS NULL THEN RAISE EXCEPTION 'Stream not found'; END IF;

  _is_admin := _caller IS NOT NULL AND (public.has_role(_caller,'admin') OR public.has_role(_caller,'owner'));
  -- Allow seller, admin, or system-invoked (auth.uid() IS NULL via cron) to rearm.
  IF _caller IS NOT NULL AND NOT _is_admin AND _caller <> _s.seller_id THEN
    RAISE EXCEPTION 'Only the seller or admin can rearm';
  END IF;

  _remaining := GREATEST(0, COALESCE(_s.quick_start_remaining, 0));
  _sec := GREATEST(5, COALESCE(_s.default_timer_sec, 30));
  _start := GREATEST(0.01, COALESCE(_s.default_starting_bid, _s.starting_bid, 1));

  IF _remaining > 0 THEN
    UPDATE public.live_streams SET
      ends_at = now() + make_interval(secs => _sec),
      starting_bid = _start,
      current_bid = _start,
      current_bidder_id = NULL,
      winner_id = NULL,
      winning_bid = NULL,
      winner_username = NULL,
      pinned_card = NULL,
      snipe_extends = 0,
      sudden_death_active = false,
      quick_start_remaining = _remaining - 1,
      last_activity_at = now(),
      last_activity_type = 'round_rearmed'
    WHERE id = _stream_id;
  ELSE
    UPDATE public.live_streams SET
      ends_at = NULL,
      current_bidder_id = NULL,
      winner_id = NULL,
      winning_bid = NULL,
      winner_username = NULL,
      pinned_card = NULL
    WHERE id = _stream_id;
  END IF;

  INSERT INTO public.audit_logs (actor_id, action, target_type, target_id, meta)
  VALUES (_caller, 'auction_rearmed', 'live_stream', _stream_id,
          jsonb_build_object('remaining', _remaining, 'timer_sec', _sec, 'starting_bid', _start));

  RETURN jsonb_build_object('ok', true, 'remaining', GREATEST(0, _remaining - 1));
END;
$function$

CREATE OR REPLACE FUNCTION public.recalc_seller_trust(_user_id uuid)
 RETURNS seller_trust
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _delivered INTEGER;
  _total_recent INTEGER;
  _refunds INTEGER;
  _disputes INTEGER;
  _late INTEGER;
  _unscanned INTEGER;
  _insurance_claims INTEGER;
  _refund_rate NUMERIC := 0;
  _dispute_rate NUMERIC := 0;
  _late_rate NUMERIC := 0;
  _tier public.seller_trust_tier;
  _instant INTEGER;
  _fraud_cap INTEGER := 100;
  _auto_freeze BOOLEAN := false;
  _row public.seller_trust;
BEGIN
  -- Strict successful-delivery count: delivered, paid, no refund, no dispute,
  -- not lost, not returned, has a valid carrier scan, no active insurance claim.
  SELECT COUNT(*) INTO _delivered
  FROM public.orders o
  WHERE o.seller_id = _user_id
    AND o.status = 'delivered'
    AND o.payment_status = 'paid'
    AND COALESCE(o.refunded_amount, 0) = 0
    AND o.lost_marked_at IS NULL
    AND o.first_scan_at IS NOT NULL
    AND o.shipping_status <> 'returned'
    AND o.insurance_status NOT IN ('claim_pending','claim_approved','reimbursed')
    AND NOT EXISTS (
      SELECT 1 FROM public.disputes d
      WHERE d.order_id = o.id
        AND d.lifecycle_status NOT IN ('resolved_seller','closed_no_action')
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.fraud_flags f
      WHERE f.user_id = _user_id
        AND f.flag_type = 'insurance_fraud'
        AND f.resolved_at IS NULL
        AND (f.details->>'order_id')::uuid = o.id
    );

  -- Fraud signals over the last 90 days
  SELECT COUNT(*) INTO _total_recent
  FROM public.orders WHERE seller_id = _user_id
    AND payment_status = 'paid'
    AND created_at > now() - interval '90 days';

  IF _total_recent >= 10 THEN
    SELECT COUNT(*) INTO _refunds FROM public.orders
      WHERE seller_id = _user_id AND payment_status = 'paid'
        AND COALESCE(refunded_amount,0) > 0
        AND created_at > now() - interval '90 days';
    SELECT COUNT(*) INTO _disputes FROM public.disputes d
      JOIN public.orders o ON o.id = d.order_id
      WHERE o.seller_id = _user_id
        AND d.created_at > now() - interval '90 days';
    SELECT COUNT(*) INTO _late FROM public.orders
      WHERE seller_id = _user_id AND is_late_shipment = true
        AND created_at > now() - interval '90 days';
    _refund_rate := _refunds::numeric / _total_recent;
    _dispute_rate := _disputes::numeric / _total_recent;
    _late_rate := _late::numeric / _total_recent;
  END IF;

  SELECT COUNT(*) INTO _unscanned FROM public.orders
    WHERE seller_id = _user_id
      AND shipping_status = 'label_created'
      AND first_scan_at IS NULL
      AND label_purchased_at < now() - interval '5 days';

  SELECT COUNT(*) INTO _insurance_claims FROM public.insurance_claims c
    JOIN public.orders o ON o.id = c.order_id
    WHERE o.seller_id = _user_id
      AND c.status IN ('approved','reimbursed')
      AND c.created_at > now() - interval '90 days';

  -- Auto-freeze on critical signals
  IF _refund_rate > 0.25 OR _dispute_rate > 0.10 OR _insurance_claims >= 5 THEN
    _auto_freeze := true;
  END IF;

  -- Soft tier cap based on fraud signals
  IF _refund_rate > 0.15 OR _dispute_rate > 0.05 OR _late_rate > 0.30
     OR _unscanned >= 3 OR _insurance_claims >= 3 THEN
    _fraud_cap := 25;   -- cap at Bronze
  ELSIF _late_rate > 0.15 OR _unscanned >= 1 THEN
    _fraud_cap := 50;   -- cap at Gold
  END IF;

  -- New tier schedule
  IF _delivered >= 200 THEN _tier := 'diamond';  _instant := 100;
  ELSIF _delivered >= 101 THEN _tier := 'platinum'; _instant := 75;
  ELSIF _delivered >= 76  THEN _tier := 'gold';     _instant := 50;
  ELSIF _delivered >= 51  THEN _tier := 'silver';   _instant := 40;
  ELSIF _delivered >= 26  THEN _tier := 'bronze';   _instant := 25;
  ELSE                          _tier := 'new';     _instant := 10;
  END IF;

  _instant := LEAST(_instant, _fraud_cap);

  INSERT INTO public.seller_trust (user_id, completed_deliveries, tier, instant_release_pct, pending_release_pct, frozen, updated_at)
  VALUES (_user_id, _delivered, _tier, _instant, 100 - _instant, _auto_freeze, now())
  ON CONFLICT (user_id) DO UPDATE
    SET completed_deliveries = EXCLUDED.completed_deliveries,
        tier = EXCLUDED.tier,
        instant_release_pct = EXCLUDED.instant_release_pct,
        pending_release_pct = EXCLUDED.pending_release_pct,
        frozen = CASE
          WHEN public.seller_trust.frozen = true THEN true  -- keep manual freezes sticky
          ELSE EXCLUDED.frozen
        END,
        updated_at = now()
  RETURNING * INTO _row;

  -- Log auto-freeze as a fraud flag so admins can review
  IF _auto_freeze THEN
    INSERT INTO public.fraud_flags (user_id, flag_type, severity, auto_action, details)
    SELECT _user_id, 'auto_freeze_payouts', 'high', 'freeze_payouts',
      jsonb_build_object(
        'refund_rate', _refund_rate,
        'dispute_rate', _dispute_rate,
        'insurance_claims_90d', _insurance_claims,
        'late_rate', _late_rate,
        'unscanned_labels', _unscanned)
    WHERE NOT EXISTS (
      SELECT 1 FROM public.fraud_flags
      WHERE user_id = _user_id AND flag_type = 'auto_freeze_payouts'
        AND resolved_at IS NULL
    );
  END IF;

  RETURN _row;
END $function$

CREATE OR REPLACE FUNCTION public.record_buyer_risk_signal(_user_id uuid, _kind text, _ref_table text DEFAULT NULL::text, _ref_id uuid DEFAULT NULL::uuid, _seller_id uuid DEFAULT NULL::uuid, _metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_weight integer;
  v_score integer;
  v_unique_sellers integer;
  v_existing uuid;
BEGIN
  IF _user_id IS NULL OR _kind IS NULL THEN
    RETURN 0;
  END IF;

  v_weight := public._buyer_signal_weight(_kind);

  INSERT INTO public.buyer_risk_signals (
    user_id, kind, severity_weight, ref_table, ref_id, seller_id, metadata
  ) VALUES (
    _user_id, _kind, v_weight, _ref_table, _ref_id, _seller_id, COALESCE(_metadata, '{}'::jsonb)
  );

  -- 30-day weighted score
  SELECT COALESCE(SUM(severity_weight), 0),
         COUNT(DISTINCT seller_id) FILTER (WHERE seller_id IS NOT NULL)
    INTO v_score, v_unique_sellers
    FROM public.buyer_risk_signals
   WHERE user_id = _user_id
     AND created_at > now() - interval '30 days';

  -- Auto-flag into existing buyer_review_queue when threshold crossed
  IF v_score >= 15 OR v_unique_sellers >= 3 OR _kind IN ('chargeback','dispute_opened') THEN
    SELECT id INTO v_existing
      FROM public.buyer_review_queue
     WHERE buyer_id = _user_id AND status = 'pending'
     LIMIT 1;

    IF v_existing IS NULL THEN
      INSERT INTO public.buyer_review_queue (buyer_id, reason, unpaid_strikes, status)
      VALUES (
        _user_id,
        format('Risk score %s (30d). Latest: %s', v_score, _kind),
        v_score,
        'pending'
      );
    ELSE
      UPDATE public.buyer_review_queue
         SET reason = format('Risk score %s (30d). Latest: %s', v_score, _kind),
             unpaid_strikes = v_score
       WHERE id = v_existing;
    END IF;
  END IF;

  -- High-severity events get a fraud_flag for staff visibility
  IF _kind IN ('chargeback','dispute_opened','bid_no_pay') THEN
    INSERT INTO public.fraud_flags (user_id, flag_type, severity, details)
    VALUES (
      _user_id,
      _kind,
      CASE WHEN _kind = 'chargeback' THEN 'critical'
           WHEN _kind = 'dispute_opened' THEN 'high'
           ELSE 'medium' END,
      jsonb_build_object('ref_table', _ref_table, 'ref_id', _ref_id, 'seller_id', _seller_id)
        || COALESCE(_metadata, '{}'::jsonb)
    );
  END IF;

  RETURN v_score;
END;
$function$

CREATE OR REPLACE FUNCTION public.record_collection_activity(_user_id uuid)
 RETURNS TABLE(current_streak integer, longest_streak integer, gained boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _row public.collection_streaks;
  _today DATE := (now() AT TIME ZONE 'utc')::date;
  _new INT;
  _gained BOOLEAN := false;
BEGIN
  SELECT * INTO _row FROM public.collection_streaks WHERE user_id = _user_id;
  IF NOT FOUND THEN
    INSERT INTO public.collection_streaks(user_id, current_streak, longest_streak, last_activity_date, total_activities)
    VALUES (_user_id, 1, 1, _today, 1)
    RETURNING * INTO _row;
    _gained := true;
  ELSIF _row.last_activity_date IS DISTINCT FROM _today THEN
    IF _row.last_activity_date = _today - 1 THEN
      _new := _row.current_streak + 1;
    ELSE
      _new := 1;
    END IF;
    UPDATE public.collection_streaks
      SET current_streak = _new,
          longest_streak = GREATEST(longest_streak, _new),
          last_activity_date = _today,
          total_activities = total_activities + 1
      WHERE user_id = _user_id
      RETURNING * INTO _row;
    _gained := true;
  END IF;
  RETURN QUERY SELECT _row.current_streak, _row.longest_streak, _gained;
END;
$function$

CREATE OR REPLACE FUNCTION public.record_shipping_adjustment(_order_id uuid, _type text, _cost_cents integer, _notes text DEFAULT NULL::text)
 RETURNS shipping_adjustments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid UUID := auth.uid(); _count INTEGER; _charge BOOLEAN := FALSE; _row public.shipping_adjustments;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  SELECT COUNT(*) INTO _count FROM public.shipping_adjustments WHERE user_id = _uid;
  IF _count >= 3 AND _cost_cents > 0 THEN
    _charge := TRUE;
    UPDATE public.profiles SET balance_cents = COALESCE(balance_cents,0) - _cost_cents WHERE id = _uid;
  END IF;
  INSERT INTO public.shipping_adjustments(user_id, order_id, adjustment_type, cost_cents, was_charged, notes)
  VALUES (_uid, _order_id, _type, _cost_cents, _charge, _notes) RETURNING * INTO _row;
  RETURN _row;
END $function$

CREATE OR REPLACE FUNCTION public.record_unpaid_auction_win(_buyer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _strikes int; _distinct_streams int; _restricted boolean := false;
BEGIN
  IF _buyer_id IS NULL THEN RETURN jsonb_build_object('ok', false); END IF;
  UPDATE public.profiles SET unpaid_strikes=COALESCE(unpaid_strikes,0)+1 WHERE id=_buyer_id RETURNING unpaid_strikes INTO _strikes;
  SELECT COUNT(DISTINCT stream_id) INTO _distinct_streams FROM public.orders WHERE buyer_id=_buyer_id AND payment_status='failed' AND stream_id IS NOT NULL;
  IF _strikes >= 10 AND _distinct_streams >= 10 THEN
    UPDATE public.profiles SET bid_restricted_until = now() + interval '30 days',
      bid_restricted_reason = 'Auto: 10+ unpaid auction wins across 10+ streams'
     WHERE id=_buyer_id AND (bid_restricted_until IS NULL OR bid_restricted_until < now() + interval '30 days');
    INSERT INTO public.buyer_review_queue (buyer_id, reason, unpaid_strikes) VALUES (_buyer_id, 'auto_unpaid_threshold', _strikes);
    INSERT INTO public.notifications (user_id, sender_id, type, body, link)
    VALUES (_buyer_id, _buyer_id, 'account_restricted',
      '⛔ Your account is on hold due to repeated unpaid auction wins. Resolve outstanding orders or contact support.', '/orders');
    _restricted := true;
  END IF;
  RETURN jsonb_build_object('ok', true, 'strikes', _strikes, 'distinct_streams', _distinct_streams, 'restricted', _restricted);
END $function$

CREATE OR REPLACE FUNCTION public.register_shipping_scan(_code text, _kind text DEFAULT 'tracking'::text)
 RETURNS TABLE(order_id uuid, prev_status text, new_status text, result text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order_id uuid; v_seller uuid; v_prev text; v_new text; v_result text;
BEGIN
  -- Try match: exact tracking number
  SELECT o.id, o.seller_id, o.prep_status
    INTO v_order_id, v_seller, v_prev
    FROM public.orders o
    WHERE o.tracking_number = _code
    ORDER BY o.created_at DESC LIMIT 1;

  -- Fallback: by order short id (first 8 chars)
  IF v_order_id IS NULL AND length(_code) >= 8 THEN
    SELECT o.id, o.seller_id, o.prep_status
      INTO v_order_id, v_seller, v_prev
      FROM public.orders o
      WHERE substr(o.id::text,1,8) = lower(substr(_code,1,8))
        AND o.seller_id = auth.uid()
      LIMIT 1;
  END IF;

  IF v_order_id IS NULL THEN
    INSERT INTO public.shipping_scans(order_id, scanned_by, code, kind, result)
      VALUES (NULL, auth.uid(), _code, _kind, 'unmatched');
    order_id := NULL; prev_status := NULL; new_status := NULL; result := 'unmatched';
    RETURN NEXT; RETURN;
  END IF;

  IF v_seller <> auth.uid() THEN
    INSERT INTO public.shipping_scans(order_id, scanned_by, code, kind, result)
      VALUES (v_order_id, auth.uid(), _code, _kind, 'mismatch');
    order_id := v_order_id; prev_status := v_prev; new_status := v_prev; result := 'mismatch';
    RETURN NEXT; RETURN;
  END IF;

  -- advance status
  v_new := CASE
    WHEN v_prev IN ('shipped','delivered') THEN v_prev
    WHEN v_prev = 'ready_for_dropoff' THEN 'ready_for_dropoff'
    ELSE 'ready_for_dropoff'
  END;

  UPDATE public.orders
    SET prep_status = v_new,
        ready_at = COALESCE(ready_at, now()),
        packed_at = COALESCE(packed_at, now()),
        dropoff_scanned_at = COALESCE(dropoff_scanned_at, now())
    WHERE id = v_order_id;

  v_result := 'matched';
  INSERT INTO public.shipping_scans(order_id, scanned_by, code, kind, result, prev_status, new_status)
    VALUES (v_order_id, auth.uid(), _code, _kind, v_result, v_prev, v_new);

  order_id := v_order_id; prev_status := v_prev; new_status := v_new; result := v_result;
  RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION public.request_payout(_amount_cents integer)
 RETURNS payout_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid UUID := auth.uid();
  _existing UUID;
  _payable BIGINT;
  _row public.payout_requests;
  _bal_before BIGINT;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF _amount_cents IS NULL OR _amount_cents <= 0 THEN RAISE EXCEPTION 'Invalid payout amount'; END IF;

  -- Per-user advisory lock prevents concurrent payout requests across tabs/clients
  PERFORM pg_advisory_xact_lock(hashtext('payout:' || _uid::text));

  SELECT id INTO _existing FROM public.payout_requests
   WHERE user_id = _uid AND status IN ('requested','processing') LIMIT 1;
  IF _existing IS NOT NULL THEN RAISE EXCEPTION 'A payout is already in progress'; END IF;

  -- Re-validate payable server-side
  SELECT payable_cents INTO _payable FROM public.compute_seller_payable(_uid);
  IF _amount_cents > _payable THEN
    RAISE EXCEPTION 'Requested amount exceeds available balance ($ %)', (_payable::numeric/100);
  END IF;

  SELECT COALESCE(balance_cents,0) INTO _bal_before FROM public.profiles WHERE id = _uid;

  INSERT INTO public.payout_requests(user_id, amount_cents, status)
  VALUES (_uid, _amount_cents, 'processing') RETURNING * INTO _row;

  INSERT INTO public.balance_audit_log(user_id, event_type, delta_cents, balance_before, balance_after, reference_table, reference_id, metadata)
  VALUES (_uid, 'payout_requested', -_amount_cents, _bal_before, _bal_before, 'payout_requests', _row.id::text, jsonb_build_object('status','processing'));

  RETURN _row;
END $function$

CREATE OR REPLACE FUNCTION public.request_platform_payout(_amount_cents bigint, _destination text, _notes text DEFAULT NULL::text)
 RETURNS platform_payouts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _row platform_payouts;
  _avail bigint;
BEGIN
  PERFORM _assert_owner();
  IF _destination NOT IN ('platform_bank','owner_personal') THEN
    RAISE EXCEPTION 'invalid destination';
  END IF;
  IF _amount_cents IS NULL OR _amount_cents <= 0 THEN
    RAISE EXCEPTION 'invalid amount';
  END IF;

  SELECT available_cents INTO _avail FROM compute_platform_available();
  IF _amount_cents > _avail THEN
    RAISE EXCEPTION 'amount exceeds available platform balance';
  END IF;

  INSERT INTO platform_payouts (requested_by, amount_cents, destination, notes)
  VALUES (auth.uid(), _amount_cents, _destination, _notes)
  RETURNING * INTO _row;

  RETURN _row;
END;
$function$

CREATE OR REPLACE FUNCTION public.request_verification(_kind text DEFAULT 'seller'::text, _note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _cur text;
  _username text;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF _kind NOT IN ('seller','live_host') THEN RAISE EXCEPTION 'Invalid verification kind'; END IF;

  SELECT verification_status, username INTO _cur, _username FROM public.profiles WHERE id = _uid;

  IF _cur = 'approved' THEN
    RETURN jsonb_build_object('status','approved','message','Already verified');
  END IF;

  UPDATE public.profiles
  SET verification_status = 'pending',
      verification_requested_at = now(),
      verification_reason = _note,
      verification_history = verification_history || jsonb_build_object(
        'event','requested','kind',_kind,'note',_note,'at',now()
      ),
      seller_status = CASE WHEN _kind = 'seller' AND seller_status = 'none' THEN 'pending' ELSE seller_status END
  WHERE id = _uid;

  -- Notify admins/owners
  INSERT INTO public.notifications (user_id, sender_id, type, body, link)
  SELECT ur.user_id, _uid, 'verification_request',
         '🪪 New ' || _kind || ' verification: @' || COALESCE(_username,'user'),
         '/admin'
  FROM public.user_roles ur
  WHERE ur.role IN ('admin','owner')
  ON CONFLICT DO NOTHING;

  RETURN jsonb_build_object('status','pending');
END;
$function$

CREATE OR REPLACE FUNCTION public.run_financial_reconciliation(_since timestamp with time zone DEFAULT (now() - '7 days'::interval))
 RETURNS TABLE(scanned_orders bigint, missing_commission bigint, missing_shipping_margin bigint, payout_drift bigint, new_alerts bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _scanned bigint := 0;
  _missing_comm bigint := 0;
  _missing_ship bigint := 0;
  _drift bigint := 0;
  _alerts bigint := 0;
  _row record;
BEGIN
  SELECT COUNT(*) INTO _scanned
  FROM orders WHERE payment_status='paid' AND created_at >= _since;

  FOR _row IN
    SELECT o.id, o.amount, o.shipping_amount, o.commission_amount
    FROM orders o
    LEFT JOIN platform_revenue pr
      ON pr.order_id = o.id AND pr.kind = 'marketplace_commission'
    WHERE o.payment_status='paid'
      AND o.created_at >= _since
      AND COALESCE(o.commission_amount,0) > 0
      AND pr.id IS NULL
  LOOP
    _missing_comm := _missing_comm + 1;
    INSERT INTO financial_integrity_alerts(severity, kind, order_id, amount_cents, details)
    SELECT 'warning','missing_commission_ledger', _row.id,
           (_row.commission_amount * 100)::bigint,
           jsonb_build_object('subtotal', _row.amount - _row.shipping_amount)
    WHERE NOT EXISTS (
      SELECT 1 FROM financial_integrity_alerts
      WHERE kind='missing_commission_ledger' AND order_id = _row.id AND resolved_at IS NULL
    );
    _alerts := _alerts + 1;
  END LOOP;

  FOR _row IN
    SELECT o.id, o.shipping_amount, o.label_cost_cents
    FROM orders o
    LEFT JOIN platform_revenue pr
      ON pr.order_id = o.id AND pr.kind = 'shipping_margin'
    WHERE o.payment_status='paid'
      AND o.created_at >= _since
      AND o.label_purchased_at IS NOT NULL
      AND pr.id IS NULL
  LOOP
    _missing_ship := _missing_ship + 1;
    INSERT INTO financial_integrity_alerts(severity, kind, order_id, amount_cents, details)
    SELECT 'warning','missing_shipping_margin', _row.id, _row.label_cost_cents,
           jsonb_build_object('shipping_charged_cents',(_row.shipping_amount*100)::int)
    WHERE NOT EXISTS (
      SELECT 1 FROM financial_integrity_alerts
      WHERE kind='missing_shipping_margin' AND order_id = _row.id AND resolved_at IS NULL
    );
    _alerts := _alerts + 1;
  END LOOP;

  FOR _row IN
    SELECT id, amount, shipping_amount, commission_amount, seller_payout_amount,
           ABS((COALESCE(commission_amount,0) + COALESCE(seller_payout_amount,0))
              - (COALESCE(amount,0) - COALESCE(shipping_amount,0))) AS drift
    FROM orders
    WHERE payment_status='paid'
      AND created_at >= _since
      AND commission_amount IS NOT NULL
      AND seller_payout_amount IS NOT NULL
      AND ABS((COALESCE(commission_amount,0) + COALESCE(seller_payout_amount,0))
            - (COALESCE(amount,0) - COALESCE(shipping_amount,0))) > 0.02
  LOOP
    _drift := _drift + 1;
    INSERT INTO financial_integrity_alerts(severity, kind, order_id, amount_cents, details)
    SELECT 'critical','payout_drift', _row.id, (_row.drift*100)::bigint,
           jsonb_build_object(
             'subtotal', _row.amount - _row.shipping_amount,
             'commission', _row.commission_amount,
             'payout', _row.seller_payout_amount
           )
    WHERE NOT EXISTS (
      SELECT 1 FROM financial_integrity_alerts
      WHERE kind='payout_drift' AND order_id = _row.id AND resolved_at IS NULL
    );
    _alerts := _alerts + 1;
  END LOOP;

  FOR _row IN
    SELECT o.id, o.tax_cents, o.tax_jurisdiction, o.final_charged_total_cents
    FROM orders o
    LEFT JOIN platform_revenue pr
      ON pr.order_id = o.id AND pr.kind = 'sales_tax_collected'
    WHERE o.payment_status='paid'
      AND o.created_at >= _since
      AND COALESCE(o.tax_cents,0) > 0
      AND (COALESCE(o.tax_jurisdiction,'') = '' OR COALESCE(o.final_charged_total_cents,0) = 0 OR pr.id IS NULL)
  LOOP
    INSERT INTO financial_integrity_alerts(severity, kind, order_id, amount_cents, details)
    SELECT 'critical','tax_integrity_gap', _row.id, _row.tax_cents,
           jsonb_build_object(
             'tax_jurisdiction', _row.tax_jurisdiction,
             'final_charged_total_cents', _row.final_charged_total_cents,
             'missing_tax_ledger', true
           )
    WHERE NOT EXISTS (
      SELECT 1 FROM financial_integrity_alerts
      WHERE kind='tax_integrity_gap' AND order_id = _row.id AND resolved_at IS NULL
    );
    _alerts := _alerts + 1;
  END LOOP;

  scanned_orders := _scanned;
  missing_commission := _missing_comm;
  missing_shipping_margin := _missing_ship;
  payout_drift := _drift;
  new_alerts := _alerts;
  RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION public.run_platform_reconciliation()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _sold int := 0;
  _auctions int := 0;
  _payments int := 0;
  _safety int := 0;
BEGIN
  BEGIN _sold := public.reconcile_sold_items(); EXCEPTION WHEN OTHERS THEN NULL; END;
  BEGIN _auctions := public.reconcile_auction_states(); EXCEPTION WHEN OTHERS THEN NULL; END;
  BEGIN _payments := public.reconcile_stale_payments(); EXCEPTION WHEN OTHERS THEN NULL; END;
  BEGIN _safety := public.apply_live_stream_safety(NULL); EXCEPTION WHEN OTHERS THEN NULL; END;

  INSERT INTO public.audit_logs (action, target_type, meta)
  VALUES ('platform_reconciliation', 'system',
          jsonb_build_object(
            'sold_fixed', _sold,
            'auctions_finalized', _auctions,
            'payments_expired', _payments,
            'safety_actions', _safety,
            'at', now()
          ));

  RETURN jsonb_build_object(
    'sold_fixed', _sold,
    'auctions_finalized', _auctions,
    'payments_expired', _payments,
    'safety_actions', _safety
  );
END;
$function$

