CREATE OR REPLACE FUNCTION public.spawn_next_recurrence()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  next_at timestamptz;
  new_id uuid;
BEGIN
  IF NEW.recurrence IS NULL OR NEW.recurrence = 'none' THEN RETURN NEW; END IF;
  IF NEW.scheduled_for IS NULL THEN RETURN NEW; END IF;
  IF NOT (OLD.status = 'scheduled' AND NEW.status IN ('live','ended')) THEN RETURN NEW; END IF;

  next_at := CASE NEW.recurrence
    WHEN 'daily' THEN NEW.scheduled_for + interval '1 day'
    WHEN 'weekly' THEN NEW.scheduled_for + interval '7 days'
    WHEN 'monthly' THEN NEW.scheduled_for + interval '1 month'
  END;

  IF NEW.recurrence_until IS NOT NULL AND next_at > NEW.recurrence_until THEN
    RETURN NEW;
  END IF;

  -- Avoid duplicate spawn
  IF EXISTS (SELECT 1 FROM public.live_streams WHERE recurrence_parent_id = COALESCE(NEW.recurrence_parent_id, NEW.id) AND scheduled_for = next_at) THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.live_streams (
    seller_id, title, category, stream_type, tcg_tags, item_description,
    listing_type, starting_bid, current_bid, current_item, min_bid_increment,
    status, is_active, scheduled_for, quick_start_enabled, default_timer_sec,
    default_starting_bid, default_condition, recurrence, recurrence_until, recurrence_parent_id
  ) VALUES (
    NEW.seller_id, NEW.title, NEW.category, NEW.stream_type, NEW.tcg_tags, NEW.item_description,
    NEW.listing_type, NEW.starting_bid, NEW.starting_bid, NEW.current_item, NEW.min_bid_increment,
    'scheduled', false, next_at, NEW.quick_start_enabled, NEW.default_timer_sec,
    NEW.default_starting_bid, NEW.default_condition, NEW.recurrence, NEW.recurrence_until,
    COALESCE(NEW.recurrence_parent_id, NEW.id)
  ) RETURNING id INTO new_id;

  -- Carry over prebid items whose vault cards are still available (or have no vault link)
  INSERT INTO public.auction_queue (
    stream_id, host_id, position, title, quantity, image_url, sale_type,
    starting_bid, duration_seconds, snipe_price, buy_now_price, voice_trigger, vault_card_id
  )
  SELECT new_id, q.host_id, q.position, q.title, q.quantity, q.image_url, q.sale_type,
         q.starting_bid, q.duration_seconds, q.snipe_price, q.buy_now_price, q.voice_trigger, q.vault_card_id
  FROM public.auction_queue q
  LEFT JOIN public.vault_cards v ON v.id = q.vault_card_id
  WHERE q.stream_id = NEW.id
    AND q.sale_type = 'prebid'
    AND (q.vault_card_id IS NULL OR v.status = 'available');

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.spin_collection_wheel(_context_key text, _context_label text DEFAULT NULL::text)
 RETURNS TABLE(slot_id uuid, label text, rarity text, reward_kind text, reward_slug text, credits integer, xp integer, icon text, color text, already_spun boolean, new_balance bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := auth.uid();
  total_w bigint;
  pick bigint;
  chosen public.collection_wheel_slots%ROWTYPE;
  existing public.collection_wheel_spins%ROWTYPE;
  ready_claim public.reward_claims%ROWTYPE;
  bal bigint;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF _context_key IS NULL OR length(_context_key) = 0 THEN RAISE EXCEPTION 'Missing set'; END IF;

  -- one spin per completed set
  SELECT * INTO existing FROM public.collection_wheel_spins
    WHERE user_id = uid AND context_key = _context_key;
  IF existing.id IS NOT NULL THEN
    SELECT balance INTO bal FROM public.credit_wallets WHERE user_id = uid;
    RETURN QUERY SELECT existing.slot_id, existing.label, existing.rarity, existing.reward_kind,
      existing.reward_slug, existing.credits, existing.xp, existing.icon, '#7c7c8a'::text,
      true, COALESCE(bal, 0);
    RETURN;
  END IF;

  -- defense in depth: the set must be marked complete (ready/claimed) before spinning
  SELECT rc.* INTO ready_claim
    FROM public.reward_claims rc
    JOIN public.reward_definitions rd ON rd.id = rc.reward_def_id
   WHERE rc.user_id = uid
     AND rd.slug = 'set_completion'
     AND rc.context_key = _context_key
     AND rc.status IN ('ready_to_claim', 'claimed');
  IF ready_claim.id IS NULL THEN
    RAISE EXCEPTION 'This set is not complete yet';
  END IF;

  -- weighted-random pick from active slots
  SELECT COALESCE(SUM(weight), 0) INTO total_w FROM public.collection_wheel_slots WHERE is_active AND weight > 0;
  IF total_w = 0 THEN RAISE EXCEPTION 'No wheel rewards configured'; END IF;

  pick := floor(random() * total_w)::bigint;
  FOR chosen IN
    SELECT * FROM public.collection_wheel_slots WHERE is_active AND weight > 0 ORDER BY created_at
  LOOP
    IF pick < chosen.weight THEN EXIT; END IF;
    pick := pick - chosen.weight;
  END LOOP;

  -- grant credits
  IF chosen.credits <> 0 THEN
    bal := public.award_credits(chosen.credits::bigint, 'wheel_spin', _context_key, chosen.label);
  ELSE
    SELECT balance INTO bal FROM public.credit_wallets WHERE user_id = uid;
  END IF;

  -- grant XP
  IF chosen.xp > 0 THEN
    PERFORM public.award_xp(chosen.xp, 'wheel_spin', _context_key);
  END IF;

  -- grant cosmetic
  IF chosen.reward_slug IS NOT NULL AND chosen.reward_kind <> 'credits' AND chosen.reward_kind <> 'xp' THEN
    INSERT INTO public.user_rewards (user_id, reward_slug, quantity)
    VALUES (uid, chosen.reward_slug, 1)
    ON CONFLICT (user_id, reward_slug) DO UPDATE
      SET quantity = public.user_rewards.quantity + 1;
  END IF;

  -- log the spin (also enforces one-per-set via UNIQUE)
  INSERT INTO public.collection_wheel_spins (
    user_id, context_key, context_label, slot_id, label, rarity,
    reward_kind, reward_slug, credits, xp, icon
  ) VALUES (
    uid, _context_key, _context_label, chosen.id, chosen.label, chosen.rarity,
    chosen.reward_kind, chosen.reward_slug, chosen.credits, chosen.xp, chosen.icon
  );

  RETURN QUERY SELECT chosen.id, chosen.label, chosen.rarity, chosen.reward_kind,
    chosen.reward_slug, chosen.credits, chosen.xp, chosen.icon, chosen.color,
    false, COALESCE(bal, 0);
END;
$function$

CREATE OR REPLACE FUNCTION public.spin_wheels_restrict_viewer_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid = OLD.seller_id THEN
    RETURN NEW;
  END IF;

  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  -- Viewers may ONLY flip is_spinning + set spin_started_at.
  -- Force every other column back to its previous value.
  NEW.id                          := OLD.id;
  NEW.stream_id                   := OLD.stream_id;
  NEW.seller_id                   := OLD.seller_id;
  NEW.title                       := OLD.title;
  NEW.mode                        := OLD.mode;
  NEW.spin_speed                  := OLD.spin_speed;
  NEW.viewer_can_spin             := OLD.viewer_can_spin;
  NEW.is_open                     := OLD.is_open;
  NEW.is_locked                   := OLD.is_locked;
  NEW.spin_ends_at                := OLD.spin_ends_at;
  NEW.spin_target_slot_id         := OLD.spin_target_slot_id;
  NEW.spin_seed                   := OLD.spin_seed;
  NEW.last_winner_username        := OLD.last_winner_username;
  NEW.last_winner_slot_label      := OLD.last_winner_slot_label;
  NEW.last_winner_at              := OLD.last_winner_at;
  NEW.pending_decision_slot_id    := OLD.pending_decision_slot_id;
  NEW.pending_decision_slot_label := OLD.pending_decision_slot_label;
  NEW.created_at                  := OLD.created_at;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.stream_payment_events_validate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.event_type NOT IN ('payment_pending','payment_paid','payment_declined','payment_recovered','payment_refunded','payment_failed','payment_retry') THEN
    RAISE EXCEPTION 'Invalid event_type: %', NEW.event_type;
  END IF;
  -- Auto-set seller_id from stream if missing
  IF NEW.seller_id IS NULL THEN
    SELECT seller_id INTO NEW.seller_id FROM public.live_streams WHERE id = NEW.stream_id;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.stream_user_bans_protect_admins()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF public.has_role(NEW.banned_user_id, 'admin') OR public.has_role(NEW.banned_user_id, 'owner') THEN
    RAISE EXCEPTION 'Admins and the owner cannot be banned';
  END IF;
  IF NEW.banned_user_id = NEW.banned_by THEN
    RAISE EXCEPTION 'Cannot ban yourself';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.support_message_notify()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _owner uuid;
  _subject text;
BEGIN
  IF NEW.is_staff = true THEN
    SELECT user_id, subject INTO _owner, _subject
      FROM public.support_tickets WHERE id = NEW.ticket_id;
    IF _owner IS NOT NULL AND _owner <> NEW.sender_id THEN
      INSERT INTO public.notifications (user_id, sender_id, type, body, link)
      VALUES (
        _owner, NEW.sender_id, 'support_reply',
        'Support replied: ' || COALESCE(LEFT(_subject, 80), 'your ticket'),
        '/?ticket=' || NEW.ticket_id::text
      );
    END IF;
  END IF;
  -- Bump ticket updated_at
  UPDATE public.support_tickets SET updated_at = now() WHERE id = NEW.ticket_id;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sweep_stuck_auctions()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _row RECORD;
  _finalized int := 0;
  _rearmed int := 0;
  _errors int := 0;
BEGIN
  -- (a) Finalize any expired auction that still has bidders attached
  FOR _row IN
    SELECT id FROM public.live_streams
     WHERE status = 'live'
       AND ends_at IS NOT NULL
       AND ends_at < now() - interval '15 seconds'
       AND winner_id IS NULL
     LIMIT 50
  LOOP
    BEGIN
      PERFORM public.finalize_auction_round(_row.id);
      _finalized := _finalized + 1;
    EXCEPTION WHEN OTHERS THEN
      _errors := _errors + 1;
      INSERT INTO public.audit_logs (actor_id, action, target_type, target_id, meta)
      VALUES (NULL, 'auction_sweep_error', 'live_stream', _row.id,
              jsonb_build_object('error', SQLERRM));
    END;
  END LOOP;

  -- (b) Auto-rearm: a finalized round whose banner has been up for >10s
  --     and remaining quick-start quantity exists.
  FOR _row IN
    SELECT id FROM public.live_streams
     WHERE status = 'live'
       AND winner_id IS NOT NULL
       AND ends_at IS NOT NULL
       AND ends_at < now() - interval '10 seconds'
       AND COALESCE(quick_start_remaining, 0) > 0
     LIMIT 50
  LOOP
    BEGIN
      PERFORM public.rearm_next_round(_row.id);
      _rearmed := _rearmed + 1;
    EXCEPTION WHEN OTHERS THEN
      _errors := _errors + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object('finalized', _finalized, 'rearmed', _rearmed, 'errors', _errors);
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_order_insurance_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status = 'submitted' OR NEW.status = 'under_review' THEN
    UPDATE public.orders SET insurance_status = 'claim_pending', payout_held = true WHERE id = NEW.order_id;
  ELSIF NEW.status = 'approved' THEN
    UPDATE public.orders SET insurance_status = 'claim_approved' WHERE id = NEW.order_id;
  ELSIF NEW.status = 'denied' THEN
    UPDATE public.orders SET insurance_status = 'claim_denied', payout_held = false WHERE id = NEW.order_id;
  ELSIF NEW.status = 'paid' THEN
    UPDATE public.orders SET insurance_status = 'reimbursed' WHERE id = NEW.order_id;
    -- Credit seller for reimbursement
    INSERT INTO public.payout_adjustments (seller_id, order_id, amount_cents, kind, notes)
    SELECT o.seller_id, o.id, NEW.reimbursed_cents, 'insurance_reimbursement',
           'Insurance claim ' || NEW.id::text
    FROM public.orders o WHERE o.id = NEW.order_id AND NEW.reimbursed_cents > 0;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_vault_listing_link()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.vault_card_id IS NOT NULL AND NEW.auction_status = 'active' THEN
      UPDATE public.vault_cards
        SET listed_listing_id = NEW.id
        WHERE id = NEW.vault_card_id;
    END IF;
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.vault_card_id IS NOT NULL AND NEW.auction_status IS DISTINCT FROM OLD.auction_status THEN
      IF NEW.auction_status = 'sold' THEN
        UPDATE public.vault_cards
          SET listed_listing_id = NULL,
              is_sold = true,
              status = 'sold',
              updated_at = now()
          WHERE id = NEW.vault_card_id;
      ELSIF NEW.auction_status IN ('cancelled','expired','ended') THEN
        UPDATE public.vault_cards
          SET listed_listing_id = NULL
          WHERE id = NEW.vault_card_id AND listed_listing_id = NEW.id;
      ELSIF NEW.auction_status = 'active' THEN
        UPDATE public.vault_cards
          SET listed_listing_id = NEW.id
          WHERE id = NEW.vault_card_id;
      END IF;
    END IF;
    RETURN NEW;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.touch_card_identities_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.unlock_achievement(_user_id uuid, _slug text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _ach_id uuid;
  _xp int;
  _inserted boolean := false;
BEGIN
  SELECT id, xp_reward INTO _ach_id, _xp
  FROM public.achievements WHERE slug = _slug;
  IF _ach_id IS NULL THEN RETURN; END IF;

  INSERT INTO public.user_achievements (user_id, achievement_id)
  VALUES (_user_id, _ach_id)
  ON CONFLICT (user_id, achievement_id) DO NOTHING
  RETURNING true INTO _inserted;

  IF _inserted AND _xp > 0 THEN
    PERFORM public.award_xp(_user_id, _xp, 'achievement:' || _slug, _ach_id);
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.user_blocks_protect_admins()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.blocker_id = NEW.blocked_id THEN
    RAISE EXCEPTION 'Cannot block yourself';
  END IF;
  IF public.has_role(NEW.blocked_id, 'admin') OR public.has_role(NEW.blocked_id, 'owner') THEN
    RAISE EXCEPTION 'Admins and the owner cannot be blocked';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_offer_amount()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.amount IS NULL OR NEW.amount <= 1 THEN
    RAISE EXCEPTION 'Offer must be greater than $1';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_order_inventory()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _listing_qty integer;
  _committed integer;
BEGIN
  IF NEW.listing_id IS NULL THEN RETURN NEW; END IF;
  SELECT quantity INTO _listing_qty FROM public.listings WHERE id = NEW.listing_id;
  IF _listing_qty IS NULL THEN RETURN NEW; END IF;

  SELECT COALESCE(SUM(quantity), 0) INTO _committed
    FROM public.orders
   WHERE listing_id = NEW.listing_id
     AND id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
     AND payment_status IN ('paid', 'awaiting_payment');

  IF _committed + COALESCE(NEW.quantity, 1) > _listing_qty THEN
    RAISE EXCEPTION 'Not enough inventory: only % left', GREATEST(0, _listing_qty - _committed);
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_queue_offer()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.amount IS NULL OR NEW.amount <= 0 THEN
    RAISE EXCEPTION 'Offer amount must be positive';
  END IF;
  IF NEW.expires_at IS NULL THEN
    NEW.expires_at := now() + interval '24 hours';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_shop_name()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.shop_name IS NOT NULL THEN
    IF length(NEW.shop_name) < 3 OR length(NEW.shop_name) > 30 THEN
      RAISE EXCEPTION 'Shop name must be 3-30 characters';
    END IF;
    IF NEW.shop_name !~ '^[A-Za-z0-9_ -]+$' THEN
      RAISE EXCEPTION 'Shop name may only contain letters, numbers, spaces, _ and -';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
